window.AtlasChapters=(window.AtlasChapters||[]).concat([{"id":61,"title":"61단계 — as ... as","html":"\u003ch1 id=\"lesson-title\" data-id=\"61\">61단계 — as ... as\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“~만큼 …하다”\u003c/strong>, 즉 \u003cstrong>같은 정도\u003c/strong>를 비교하는 표현이다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>as + 형용사/부사 + as\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>Tom is \u003cstrong>as tall as\u003c/strong> John.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>톰은 존만큼 키가 크다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>A + be동사 + as + 형용사 + as + B\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 비교급과 차이\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">비교급\u003c/h3>\n\u003cblockquote>\n\u003cp>Tom is \u003cstrong>taller than\u003c/strong> John.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>톰은 존보다 더 크다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">같은 정도\u003c/h3>\n\u003cblockquote>\n\u003cp>Tom is \u003cstrong>as tall as\u003c/strong> John.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>톰은 존만큼 크다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>-er / more ... than = 더 ~하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>as ... as = ~만큼 ~하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 형용사는 원급 그대로\u003c/h2>\n\u003cp>\u003ccode>as ... as\u003c/code> 사이에는 비교급을 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ as tall as\u003cbr>❌ as taller as\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ as expensive as\u003cbr>❌ as more expensive as\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 \u003ccode>as ... as\u003c/code> 자체가 이미 비교 구조이기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 부사도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>She runs \u003cstrong>as fast as\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 나만큼 빨리 달린다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>fast\u003c/code>는 \u003ccode>runs\u003c/code>를 설명하므로 부사 역할이다.\u003c/p>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>He works \u003cstrong>as hard as\u003c/strong> his brother.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 형제만큼 열심히 일한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 부정형 \u003ccode>not as ... as\u003c/code>\u003c/h2>\n\u003cp>아주 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>not as + 형용사 + as\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~만큼 …하지 않다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My car is \u003cstrong>not as expensive as\u003c/strong> yours.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내 차는 네 차만큼 비싸지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 상대적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>네 차가 더 비싸다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">비교급으로 바꿀 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>My car isn&#39;t as expensive as yours.\u003c/p>\n\u003c/blockquote>\n\u003cp>≈\u003c/p>\n\u003cblockquote>\n\u003cp>Your car is more expensive than mine.\u003c/p>\n\u003c/blockquote>\n\u003cp>관점을 바꿔 말한 것이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>not so ... as\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>not so ... as\u003c/p>\n\u003c/blockquote>\n\u003cp>도 가능하지만 현대 영어에서는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>not as ... as\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 더 흔하다.\u003c/p>\n\u003cp>초급에서는 \u003ccode>not as ... as\u003c/code>를 기본으로 익히면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. \u003ccode>as much as\u003c/code>\u003c/h2>\n\u003cp>불가산명사의 양을 비교할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I don&#39;t drink \u003cstrong>as much coffee as\u003c/strong> you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 너만큼 커피를 많이 마시지 않는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>as much + 불가산명사 + as\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. \u003ccode>as many as\u003c/code>\u003c/h2>\n\u003cp>가산명사 복수의 개수를 비교한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>as many books as\u003c/strong> you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 너만큼 많은 책을 가지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>as many + 복수명사 + as\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">9. 비교\u003c/h2>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">불가산\u003c/h3>\n\u003cblockquote>\n\u003cp>as much water as\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">가산 복수\u003c/h3>\n\u003cblockquote>\n\u003cp>as many books as\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에서 배운 \u003ccode>much / many\u003c/code>와 같은 원리다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. \u003ccode>twice as ... as\u003c/code>\u003c/h2>\n\u003cp>배수를 표현할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>This room is \u003cstrong>twice as big as\u003c/strong> that one.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 방은 저 방의 두 배만큼 크다.\u003c/p>\n\u003c/blockquote>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>three times as expensive as\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>세 배 비싼\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This car is three times as expensive as mine.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">핵심\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">같은 정도\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>as + 형용사/부사 + as\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is as tall as me.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">같은 정도가 아님\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>not as + 형용사/부사 + as\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She isn&#39;t as tall as me.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">수량\u003c/h3>\n\u003cblockquote>\n\u003cp>as much water as\u003cbr>as many books as\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>She is \u003cstrong>as tall as / as taller as\u003c/strong> me.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>This car is \u003cstrong>not as expensive as / not more expensive as\u003c/strong> mine.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He runs \u003cstrong>as fast as / as faster as\u003c/strong> his brother.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I don&#39;t drink \u003cstrong>as much coffee as / as many coffee as\u003c/strong> you.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She has \u003cstrong>as many books as / as much books as\u003c/strong> me.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>This room is \u003cstrong>twice as big as / twice bigger as\u003c/strong> that one.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>62단계 — \u003c/strong>\u003cstrong>\u003ccode>used to / be used to / get used to\u003c/code>\u003c/strong>\u003cstrong> 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 비교급과 차이","depth":2},{"id":"reading-3","label":"비교급","depth":3},{"id":"reading-4","label":"같은 정도","depth":3},{"id":"reading-5","label":"3. 형용사는 원급 그대로","depth":2},{"id":"reading-6","label":"4. 부사도 가능","depth":2},{"id":"reading-7","label":"5. 부정형 not as ... as","depth":2},{"id":"reading-8","label":"비교급으로 바꿀 수도 있다","depth":2},{"id":"reading-9","label":"6. not so ... as","depth":2},{"id":"reading-10","label":"7. as much as","depth":2},{"id":"reading-11","label":"8. as many as","depth":2},{"id":"reading-12","label":"9. 비교","depth":2},{"id":"reading-13","label":"불가산","depth":3},{"id":"reading-14","label":"가산 복수","depth":3},{"id":"reading-15","label":"10. twice as ... as","depth":2},{"id":"reading-16","label":"핵심","depth":2},{"id":"reading-17","label":"같은 정도","depth":3},{"id":"reading-18","label":"같은 정도가 아님","depth":3},{"id":"reading-19","label":"수량","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"notion","characters":2328,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-15","topic-12":"reading-16"}},{"id":62,"title":"62단계 — used to / be used to / get used to","html":"\u003ch1 id=\"lesson-title\" data-id=\"62\">62단계 — used to / be used to / get used to\u003c/h1>\n\u003cp>셋은 모양이 비슷하지만 \u003cstrong>뜻과 뒤에 오는 형태가 완전히 다르다.\u003c/strong>\u003c/p>\n\u003cp>핵심부터 보면:\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">표현\u003c/th>\u003cth scope=\"col\">의미\u003c/th>\u003cth scope=\"col\">뒤의 형태\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>\u003cstrong>used to do\u003c/strong>\u003c/td>\u003ctd>예전에는 ~했다\u003c/td>\u003ctd>동사원형\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cstrong>be used to ~\u003c/strong>\u003c/td>\u003ctd>~에 익숙하다\u003c/td>\u003ctd>명사 / \u003ccode>-ing\u003c/code>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cstrong>get used to ~\u003c/strong>\u003c/td>\u003ctd>~에 익숙해지다\u003c/td>\u003ctd>명사 / \u003ccode>-ing\u003c/code>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>used to + 동사원형\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>예전에는 ~했지만 지금은 그렇지 않다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>used to play\u003c/strong> games a lot.\u003cbr>나는 예전에 게임을 많이 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 지금은 예전만큼 하지 않는다는 뉘앙스가 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">과거의 습관\u003c/h2>\n\u003cblockquote>\n\u003cp>I used to drink coffee every morning.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 예전에 매일 아침 커피를 마셨다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">과거의 상태도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>I used to live in Seoul.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 예전에 서울에 살았다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This building used to be a school.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 건물은 예전에 학교였다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 \u003ccode>used to\u003c/code>는 행동뿐 아니라 \u003cstrong>과거 상태\u003c/strong>에도 쓸 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 지금도 계속하는 습관에는 쓰지 않는다\u003c/h2>\n\u003cblockquote>\n\u003cp>I used to live in Busan.\u003c/p>\n\u003c/blockquote>\n\u003cp>이라고 하면 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>예전에는 부산에 살았지만 \u003cstrong>지금은 아니다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미가 생긴다.\u003c/p>\n\u003cp>지금도 부산에 산다면:\u003c/p>\n\u003cblockquote>\n\u003cp>I live in Busan.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는 기간까지 말하면:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve lived in Busan for ten years.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 부정문\u003c/h2>\n\u003cp>표준적인 기본형은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>didn&#39;t use to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>didn&#39;t use to like\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 예전에는 커피를 좋아하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>didn&#39;t\u003c/code>이 이미 과거를 표시하기 때문에:\u003c/p>\n\u003cblockquote>\n\u003cp>used → \u003cstrong>use\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>로 돌아간다.\u003c/p>\n\u003cp>따라서 학습 단계에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ didn&#39;t use to\u003cbr>❌ didn&#39;t used to\u003c/p>\n\u003c/blockquote>\n\u003cp>로 익힌다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 의문문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Did + 주어 + use to + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Did you use to play\u003c/strong> soccer?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>예전에 축구 했어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Did she use to live here?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 예전에 여기 살았어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>be used to\u003c/code>\u003c/h2>\n\u003cp>이번에는 전혀 다른 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be used to = ~에 익숙하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>used to cold weather\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 추운 날씨에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>used\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>익숙한\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 상태를 나타낸다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 뒤에 명사가 온다\u003c/h2>\n\u003cblockquote>\n\u003cp>be used to \u003cstrong>the weather\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>be used to \u003cstrong>this job\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>be used to \u003cstrong>noise\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m used to this job.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 이 일에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 행동을 넣으면 \u003ccode>-ing\u003c/code>\u003c/h2>\n\u003cp>이게 가장 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m used to \u003cstrong>getting up early\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일찍 일어나는 것에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I&#39;m used to get up early.\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아닐까?\u003c/p>\n\u003cp>여기서 \u003ccode>to\u003c/code>는 \u003cstrong>to부정사의 to가 아니라 전치사\u003c/strong>이기 때문이다.\u003c/p>\n\u003cp>전치사 뒤에서 동작을 말하려면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>동명사 -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 두 \u003ccode>to\u003c/code>를 비교\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">\u003ccode>used to do\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I used to \u003cstrong>get up\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기의 \u003ccode>to\u003c/code>:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>예전에는 일찍 일어났다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">\u003ccode>be used to doing\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m used to \u003cstrong>getting up\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기의 \u003ccode>to\u003c/code>:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>전치사 + 동명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>일찍 일어나는 것에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>겉모양만 비슷하고 \u003cstrong>문법 구조 자체가 다르다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. \u003ccode>get used to\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~에 익숙해지다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>be used to\u003c/code>가 현재 상태라면,\u003c/p>\n\u003cp>\u003ccode>get used to\u003c/code>는 \u003cstrong>그 상태로 변화하는 과정\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">be used to\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m used to working late.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 야근에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 익숙한 상태.\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">get used to\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m getting used to working late.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 야근에 익숙해지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 적응 중.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. 시제도 자유롭게 바뀐다\u003c/h2>\n\u003cp>\u003ccode>get\u003c/code>이 일반동사이므로 시제를 바꿀 수 있다.\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>get used to\u003c/strong> things quickly.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">현재진행\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>getting used to\u003c/strong> my new job.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>새 직장에 익숙해지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">과거\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>got used to\u003c/strong> waking up early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일찍 일어나는 것에 익숙해졌다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">미래\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;ll \u003cstrong>get used to\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>곧 익숙해질 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 표현은 회화에서 아주 많이 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">11. 세 문장을 비교하면 확실하다\u003c/h2>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">예전에 그랬다\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>used to wake up\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>예전에는 일찍 일어났다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">지금 익숙하다\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>used to waking up\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일찍 일어나는 것에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">익숙해지는 중이다\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>getting used to waking up\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일찍 일어나는 것에 익숙해지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">12. 문장 구조를 정확히 나누면\u003c/h2>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">\u003ccode>used to do\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>used to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">\u003ccode>be used to\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + used to + 명사/-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">\u003ccode>get used to\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>get + used to + 명사/-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is used to working\u003c/strong> late.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어가 \u003ccode>she\u003c/code>라서 \u003ccode>is\u003c/code>.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>used to work\u003c/strong> late.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>used to\u003c/code> 자체가 과거 표현이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">13. \u003ccode>I&#39;m used to it\u003c/code>\u003c/h2>\n\u003cp>매우 자주 쓰는 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I&#39;m used to it.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나 그거 익숙해.\u003c/p>\n\u003c/blockquote>\n\u003cp>반대로:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m not used to it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그거에 익숙하지 않아.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll get used to it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>곧 익숙해질 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 세 문장은 통째로 익혀도 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-30\" data-reading-anchor=\"reading-30\">핵심\u003c/h2>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">과거 습관\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>used to work\u003c/strong> here.\u003cbr>예전에 여기서 일했다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-32\" data-reading-anchor=\"reading-32\">익숙한 상태\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>used to working\u003c/strong> here.\u003cbr>여기서 일하는 것에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-33\" data-reading-anchor=\"reading-33\">익숙해지는 과정\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>getting used to working\u003c/strong> here.\u003cbr>여기서 일하는 것에 익숙해지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>used to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be/get used to + 명사 또는 -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-34\" data-reading-anchor=\"reading-34\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I used to \u003cstrong>play / playing\u003c/strong> games a lot.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;m used to \u003cstrong>get / getting\u003c/strong> up early.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She is used to \u003cstrong>work / working\u003c/strong> late.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;m \u003cstrong>getting used to / used to\u003c/strong> my new job.\u003c/p>\n\u003cp> → 새 직장에 적응하는 중\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>used to live / am used to live\u003c/strong> in Seoul.\u003c/p>\n\u003cp> → 예전에 서울에 살았다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Did you \u003cstrong>use to / used to\u003c/strong> play soccer?\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>63단계 — \u003c/strong>\u003cstrong>\u003ccode>would\u003c/code>\u003c/strong>\u003cstrong>의 기본 용법: 미래의 과거 / 정중한 표현 / 가정\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. used to + 동사원형","depth":2},{"id":"reading-2","label":"과거의 습관","depth":2},{"id":"reading-3","label":"과거의 상태도 가능","depth":2},{"id":"reading-4","label":"2. 지금도 계속하는 습관에는 쓰지 않는다","depth":2},{"id":"reading-5","label":"3. 부정문","depth":2},{"id":"reading-6","label":"4. 의문문","depth":2},{"id":"reading-7","label":"5. be used to","depth":2},{"id":"reading-8","label":"6. 뒤에 명사가 온다","depth":2},{"id":"reading-9","label":"7. 행동을 넣으면 -ing","depth":2},{"id":"reading-10","label":"8. 두 to를 비교","depth":2},{"id":"reading-11","label":"used to do","depth":3},{"id":"reading-12","label":"be used to doing","depth":3},{"id":"reading-13","label":"9. get used to","depth":2},{"id":"reading-14","label":"be used to","depth":3},{"id":"reading-15","label":"get used to","depth":3},{"id":"reading-16","label":"10. 시제도 자유롭게 바뀐다","depth":2},{"id":"reading-17","label":"현재","depth":3},{"id":"reading-18","label":"현재진행","depth":3},{"id":"reading-19","label":"과거","depth":3},{"id":"reading-20","label":"미래","depth":3},{"id":"reading-21","label":"11. 세 문장을 비교하면 확실하다","depth":2},{"id":"reading-22","label":"예전에 그랬다","depth":3},{"id":"reading-23","label":"지금 익숙하다","depth":3},{"id":"reading-24","label":"익숙해지는 중이다","depth":3},{"id":"reading-25","label":"12. 문장 구조를 정확히 나누면","depth":2},{"id":"reading-26","label":"used to do","depth":3},{"id":"reading-27","label":"be used to","depth":3},{"id":"reading-28","label":"get used to","depth":3},{"id":"reading-29","label":"13. I'm used to it","depth":2},{"id":"reading-30","label":"핵심","depth":2},{"id":"reading-31","label":"과거 습관","depth":3},{"id":"reading-32","label":"익숙한 상태","depth":3},{"id":"reading-33","label":"익숙해지는 과정","depth":3},{"id":"reading-34","label":"연습","depth":2}],"origin":"notion","characters":4016,"aliases":{"structure":"reading-25","examples":"concept","contrast":"reading-10","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-13","topic-12":"reading-16"}},{"id":63,"title":"63단계 — would 기본 용법","html":"\u003ch1 id=\"lesson-title\" data-id=\"63\">63단계 — would 기본 용법\u003c/h1>\n\u003cp>\u003ccode>would\u003c/code>는 한 가지 뜻으로만 외우면 안 된다.\u003c/p>\n\u003cp>가장 기본적인 세 가지는:\u003c/p>\n\u003col>\n\u003cli>\u003cp>\u003cstrong>과거에서 바라본 미래\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>정중한 표현\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>가정적인 상황\u003c/strong>\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>would\u003c/code>의 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I would go.\u003cbr>She would come.\u003cbr>They would help.\u003c/p>\n\u003c/blockquote>\n\u003cp>항상 동사원형이다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ would goes\u003cbr>❌ would went\u003cbr>✅ would go\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>will\u003c/code>, \u003ccode>can\u003c/code>, \u003ccode>should\u003c/code>와 같은 조동사 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 과거에서 바라본 미래\u003c/h2>\n\u003cp>현재 기준의 미래:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>will come\u003c/strong> tomorrow.\u003cbr>그는 내일 올 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그런데 과거 시점에서 미래를 바라보면:\u003c/p>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>would come\u003c/strong> the next day.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 다음 날 올 거라고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>will → would\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 될 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">시간 흐름\u003c/h2>\n\u003cp>어제 그가 말했다:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;I will call you.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>오늘 그 말을 전달하면:\u003c/p>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>would call\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003cp>그가 당시 기준으로는 \u003cstrong>앞으로 전화할 것\u003c/strong>이라고 말한 것이다.\u003c/p>\n\u003cp>그래서 \u003ccode>would\u003c/code>를 흔히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>will의 과거형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라고 배우지만, 이것만으로 모든 \u003ccode>would\u003c/code>를 설명할 수는 없다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. 정중한 표현\u003c/h2>\n\u003cp>\u003ccode>would\u003c/code>는 말을 더 부드럽게 만들 때 매우 자주 쓴다.\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">\u003ccode>Would you like ...?\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you like some coffee?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>커피 좀 드실래요?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Do you want coffee?\u003c/code>도 가능하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>Would you like ...?\u003c/p>\n\u003c/blockquote>\n\u003cp>가 더 부드럽고 공손하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>Would you + 동사원형?\u003c/code>\u003c/h2>\n\u003cp>부탁할 때도 사용한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you open the window?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>창문 좀 열어주시겠어요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you help me?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>저 좀 도와주시겠어요?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>will\u003c/code>보다 조금 더 정중하게 들릴 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>I&#39;d like ...\u003c/code>\u003c/h2>\n\u003cp>아주 중요한 회화 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I&#39;d like ...\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d = I would\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">명사를 원할 때\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d like \u003cstrong>a coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>커피 한 잔 주세요.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">행동하고 싶을 때\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d like \u003cstrong>to order\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>주문하고 싶습니다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would like + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would like to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">\u003ccode>want\u003c/code>와 비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I want coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 맞다.\u003c/p>\n\u003cp>하지만 상황에 따라 다소 직접적으로 들릴 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d like coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>좀 더 부드럽다.\u003c/p>\n\u003cp>특히 식당·호텔·가게 등에서 많이 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. 가정적인 상황\u003c/h2>\n\u003cp>\u003ccode>would\u003c/code>의 아주 중요한 용법이다.\u003c/p>\n\u003cblockquote>\n\u003cp>If I had more time, I \u003cstrong>would travel\u003c/strong> more.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시간이 더 있다면 여행을 더 많이 할 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 시간이 충분하지 않다\u003c/p>\n\u003c/blockquote>\n\u003cp>는 뉘앙스가 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. \u003ccode>if\u003c/code> 조건문과 연결\u003c/h2>\n\u003cp>앞에서 배운 현실적인 미래 조건:\u003c/p>\n\u003cblockquote>\n\u003cp>If I have time, I \u003cstrong>will go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시간이 있으면 갈게.\u003c/p>\n\u003c/blockquote>\n\u003cp>이건 실제로 시간이 생길 가능성이 있는 조건이다.\u003c/p>\n\u003chr>\n\u003cp>가정적인 조건:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had time, I \u003cstrong>would go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시간이 있다면 갈 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재 현실과 거리가 있는 느낌이다.\u003c/p>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>if + 현재 → will\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>if + 과거형 → would\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 구조는 다음 단계에서 자세히 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. \u003ccode>would\u003c/code> 자체가 과거 뜻은 아니다\u003c/h2>\n\u003cp>이 부분이 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I would go if I had time.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>would go\u003c/code>는 과거에 갔다는 뜻이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>갈 텐데\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 현재/미래의 가정이다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>would = 무조건 과거 ❌\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. 과거의 반복 습관\u003c/h2>\n\u003cp>\u003ccode>would\u003c/code>는 과거에 반복해서 하던 행동을 표현하기도 한다.\u003c/p>\n\u003cblockquote>\n\u003cp>When I was a child, I \u003cstrong>would play outside every day\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어렸을 때 나는 매일 밖에서 놀곤 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이때:\u003c/p>\n\u003cblockquote>\n\u003cp>would + 동사원형\u003c/p>\n\u003c/blockquote>\n\u003cp>= \u003cstrong>~하곤 했다\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. \u003ccode>used to\u003c/code>와 비슷하다\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>used to play\u003c/strong> outside every day.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>would play\u003c/strong> outside every day.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 과거의 반복 행동을 말할 수 있다.\u003c/p>\n\u003cp>하지만 차이가 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">\u003ccode>used to\u003c/code>는 과거 상태도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>I used to \u003cstrong>live\u003c/strong> in Seoul.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>예전에 서울에 살았다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I used to \u003cstrong>be\u003c/strong> shy.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>예전에는 수줍음이 많았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">\u003ccode>would\u003c/code>는 보통 반복 행동에 사용\u003c/h2>\n\u003cblockquote>\n\u003cp>When I was young, I would play outside every day.\u003c/p>\n\u003c/blockquote>\n\u003cp>자연스럽다.\u003c/p>\n\u003cp>하지만 상태에는 보통 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I would be shy.\u003cbr>= “예전에 수줍음이 많았다”라는 의미로는 부적절\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ I used to be shy.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>used to = 과거 행동 + 과거 상태\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>would = 과거 반복 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>으로 먼저 구분하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. \u003ccode>wouldn&#39;t\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>would not → \u003cstrong>wouldn&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I wouldn&#39;t do that.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나라면 그렇게 안 할 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 표현은 단순한 미래 부정이라기보다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>내가 그런 상황이라면 하지 않을 것이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 가정적인 느낌이 많다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">12. \u003ccode>Would you like to ...?\u003c/code>\u003c/h2>\n\u003cp>통째로 익혀두면 좋다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you like to come with us?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리랑 같이 가실래요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you like to sit down?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>앉으시겠어요?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you like to + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">핵심\u003c/h2>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">과거에서 바라본 미래\u003c/h3>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>would call\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">정중한 표현\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you like\u003c/strong> some coffee?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>I&#39;d like to order.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">가정\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>would go\u003c/strong> if I had time.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">과거 반복 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>When I was young, I \u003cstrong>would play\u003c/strong> outside every day.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 항상:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>He said he \u003cstrong>would come / would came\u003c/strong> later.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Would you like / Do you would like\u003c/strong> some coffee?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;d like \u003cstrong>to order / ordering\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I had more time, I \u003cstrong>would travel / will traveled\u003c/strong> more.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>When I was a child, I \u003cstrong>would play / would played\u003c/strong> outside every day.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“예전에는 수줍음이 많았다.”\u003c/p>\n\u003cp> → I \u003cstrong>used to be / would be\u003c/strong> shy.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>64단계 — 가정법 과거 \u003c/strong>\u003cstrong>\u003ccode>If I had..., I would...\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. would의 기본 구조","depth":2},{"id":"reading-2","label":"2. 과거에서 바라본 미래","depth":2},{"id":"reading-3","label":"시간 흐름","depth":2},{"id":"reading-4","label":"3. 정중한 표현","depth":2},{"id":"reading-5","label":"Would you like ...?","depth":3},{"id":"reading-6","label":"4. Would you + 동사원형?","depth":2},{"id":"reading-7","label":"5. I'd like ...","depth":2},{"id":"reading-8","label":"명사를 원할 때","depth":3},{"id":"reading-9","label":"행동하고 싶을 때","depth":3},{"id":"reading-10","label":"want와 비교","depth":2},{"id":"reading-11","label":"6. 가정적인 상황","depth":2},{"id":"reading-12","label":"7. if 조건문과 연결","depth":2},{"id":"reading-13","label":"8. would 자체가 과거 뜻은 아니다","depth":2},{"id":"reading-14","label":"9. 과거의 반복 습관","depth":2},{"id":"reading-15","label":"10. used to와 비슷하다","depth":2},{"id":"reading-16","label":"used to는 과거 상태도 가능","depth":2},{"id":"reading-17","label":"would는 보통 반복 행동에 사용","depth":2},{"id":"reading-18","label":"11. wouldn't","depth":2},{"id":"reading-19","label":"12. Would you like to ...?","depth":2},{"id":"reading-20","label":"핵심","depth":2},{"id":"reading-21","label":"과거에서 바라본 미래","depth":3},{"id":"reading-22","label":"정중한 표현","depth":3},{"id":"reading-23","label":"가정","depth":3},{"id":"reading-24","label":"과거 반복 행동","depth":3},{"id":"reading-25","label":"연습","depth":2}],"origin":"notion","characters":3700,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-10","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-6","topic-6":"reading-7","topic-7":"reading-10","topic-8":"reading-11","topic-9":"reading-12","topic-10":"reading-13","topic-11":"reading-14","topic-12":"reading-15"}},{"id":64,"title":"64단계 — 가정법 과거","html":"\u003ch1 id=\"lesson-title\" data-id=\"64\">64단계 — 가정법 과거\u003c/h1>\n\u003cp>이번에는 \u003cstrong>현재 사실과 다르거나, 현실 가능성이 낮은 상황을 가정\u003c/strong>하는 표현을 배운다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 주어 + 과거형, 주어 + would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had more money, I would buy a bigger house.\u003cbr>돈이 더 많다면 더 큰 집을 살 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 실제 상황은:\u003c/p>\n\u003cblockquote>\n\u003cp>지금은 돈이 충분하지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뉘앙스가 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 현실적인 조건과 비교\u003c/h2>\n\u003cp>앞에서 배운 일반 조건문:\u003c/p>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>have\u003c/strong> enough money, I \u003cstrong>will buy\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>돈이 충분하면 그것을 살 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>이건 실제로 돈이 생길 가능성이 있다고 본다.\u003c/p>\n\u003chr>\n\u003cp>가정법:\u003c/p>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had\u003c/strong> enough money, I \u003cstrong>would buy\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>돈이 충분하다면 그것을 살 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재 현실에서는 돈이 충분하지 않거나, 가능성을 낮게 보고 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 핵심 차이\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">현실적인 미래\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 현재형, will + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If it rains, I&#39;ll stay home.\u003c/p>\n\u003c/blockquote>\n\u003cp>비가 올 수도 있다고 실제 가능성을 열어둔다.\u003c/p>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">비현실적·가상적인 상황\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 과거형, would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I were rich, I would travel the world.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 부자라면 세계여행을 할 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는 부자가 아니라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 왜 현재 이야기인데 과거형을 쓰나?\u003c/h2>\n\u003cp>중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had\u003c/strong> more time...\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>had\u003c/code>는 반드시 \u003cstrong>과거 시간\u003c/strong>을 뜻하는 게 아니다.\u003c/p>\n\u003cp>영어에서는 과거형을 이용해:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>현실에서 한 단계 떨어진 가정\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 표현한다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>과거형 = 과거 시간\u003c/p>\n\u003c/blockquote>\n\u003cp>뿐 아니라\u003c/p>\n\u003cblockquote>\n\u003cp>과거형 = 현실과 거리 두기\u003c/p>\n\u003c/blockquote>\n\u003cp>역할도 할 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>If I were...\u003c/code>\u003c/h2>\n\u003cp>be동사는 특히 중요하다.\u003c/p>\n\u003cp>일반 과거형에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>I was\u003cbr>he was\u003cbr>she was\u003c/p>\n\u003c/blockquote>\n\u003cp>를 배웠다.\u003c/p>\n\u003cp>하지만 가정법에서는 전통적으로 모든 주어에:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>were\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 사용할 수 있다.\u003c/p>\n\u003cp>특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If I were you\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 거의 고정 표현처럼 매우 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">예\u003c/h2>\n\u003cblockquote>\n\u003cp>If I were rich, I would buy a house by the sea.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 부자라면 바닷가에 집을 살 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I were you, I wouldn&#39;t do that.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 너라면 그렇게 안 할 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 내가 \u003ccode>you\u003c/code>가 될 수 없으므로 아주 명확한 가정이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. \u003ccode>was\u003c/code>도 들리는데?\u003c/h2>\n\u003cp>현대 회화에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>If I was...\u003c/p>\n\u003c/blockquote>\n\u003cp>도 실제로 많이 쓰인다.\u003c/p>\n\u003cp>하지만 \u003cstrong>명백한 가정 상황\u003c/strong>을 학습할 때는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If I were...\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 기본형으로 익히는 것이 좋다.\u003c/p>\n\u003cp>특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If I were you\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 그대로 익혀두면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 일반동사\u003c/h2>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">have\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had\u003c/strong> more time, I would read more.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">know\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>knew\u003c/strong> the answer, I would tell you.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">live\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>lived\u003c/strong> closer, I would visit you more often.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">speak\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>spoke\u003c/strong> English better, I would travel alone.\u003c/p>\n\u003c/blockquote>\n\u003cp>모두 과거형이지만 현재의 가정을 나타낼 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. 결과절은 \u003ccode>would + 동사원형\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had more time, I \u003cstrong>would exercise\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ would exercised\u003cbr>❌ would exercises\u003cbr>✅ would exercise\u003c/p>\n\u003c/blockquote>\n\u003cp>조동사 뒤에는 항상 동사원형이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. \u003ccode>could\u003c/code>도 사용할 수 있다\u003c/h2>\n\u003cp>결과 부분에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>could = ~할 수 있을 텐데\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had more time, I \u003cstrong>could study\u003c/strong> English more.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시간이 더 있다면 영어를 더 공부할 수 있을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>would study\u003cbr>공부할 텐데\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>could study\u003cbr>공부할 수 있을 텐데\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">9. \u003ccode>might\u003c/code>도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had more free time, I \u003cstrong>might start\u003c/strong> a new hobby.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여유 시간이 더 있다면 새로운 취미를 시작할지도 모르겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 결과절에는 꼭 \u003ccode>would\u003c/code>만 가능한 것은 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>would = ~할 텐데\u003cbr>could = ~할 수 있을 텐데\u003cbr>might = ~할지도 모르는데\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">10. \u003ccode>if\u003c/code>절에는 보통 \u003ccode>would\u003c/code>를 쓰지 않는다\u003c/h2>\n\u003cp>기본 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ If I \u003cstrong>had\u003c/strong> time, I \u003cstrong>would go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ If I \u003cstrong>would have\u003c/strong> time, I would go.\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 하지 않는다.\u003c/p>\n\u003cp>\u003ccode>would\u003c/code>는 결과절에 둔다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. 실제 상황을 추론할 수 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had a car, I would drive to work.\u003c/p>\n\u003c/blockquote>\n\u003cp>자연스럽게:\u003c/p>\n\u003cblockquote>\n\u003cp>지금은 차가 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이 깔려 있다.\u003c/p>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>If I knew her number, I would call her.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 지금은 전화번호를 모른다.\u003c/p>\n\u003cp>즉 가정법은 자주 \u003cstrong>반대되는 현재 사실\u003c/strong>을 암시한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">12. \u003ccode>If I were you\u003c/code>\u003c/h2>\n\u003cp>매우 중요한 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If I were you, I would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>내가 너라면 ~할 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는 조언으로 많이 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>If I were you, I&#39;d wait.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 너라면 기다릴 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I&#39;d\u003c/code>:\u003c/p>\n\u003cblockquote>\n\u003cp>I would\u003c/p>\n\u003c/blockquote>\n\u003cp>의 축약형이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">13. \u003ccode>should\u003c/code>와 비교\u003c/h2>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">직접적인 조언\u003c/h3>\n\u003cblockquote>\n\u003cp>You should rest.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>쉬는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">내가 너라면\u003c/h3>\n\u003cblockquote>\n\u003cp>If I were you, I would rest.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 너라면 쉴 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째가 상대적으로 더 간접적인 조언이 될 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">14. 순서를 바꿀 수 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had more time, I would exercise.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>I would exercise if I had more time.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 같다.\u003c/p>\n\u003cp>\u003ccode>if절\u003c/code>이 앞에 오면 보통 쉼표를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">15. 현실 조건문과 가정법 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">현실 가능성\u003c/th>\u003cth scope=\"col\">가정\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>If I \u003cstrong>have\u003c/strong> time, I&#39;ll go.\u003c/td>\u003ctd>If I \u003cstrong>had\u003c/strong> time, I&#39;d go.\u003c/td>\u003c/tr>\u003ctr>\u003ctd>If she \u003cstrong>comes\u003c/strong>, I&#39;ll talk to her.\u003c/td>\u003ctd>If she \u003cstrong>came\u003c/strong>, I&#39;d talk to her.\u003c/td>\u003c/tr>\u003ctr>\u003ctd>If I \u003cstrong>am\u003c/strong> free, I&#39;ll help.\u003c/td>\u003ctd>If I \u003cstrong>were\u003c/strong> free, I&#39;d help.\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cp>핵심은 \u003cstrong>시간 차이가 아니라 현실성의 차이\u003c/strong>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">핵심\u003c/h2>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">실제 가능성이 있는 조건\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 현재형, will + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I have time, I&#39;ll go.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">현재와 다른 가정\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 과거형, would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I had time, I&#39;d go.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 대표 표현:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If I were you, I would...\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>If I \u003cstrong>have / had\u003c/strong> more money, I would buy a new car.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I were you, I \u003cstrong>would wait / waited\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If she \u003cstrong>knew / knows\u003c/strong> the answer, she would tell us.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I had more time, I \u003cstrong>could study / could studied\u003c/strong> more.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I \u003cstrong>were / am\u003c/strong> rich, I would travel the world.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“시간이 있으면 갈게.”처럼 실제 가능성이 있는 경우\u003c/p>\n\u003cp> → If I \u003cstrong>have / had\u003c/strong> time, I&#39;ll go.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>65단계 — 가정법 과거완료 \u003c/strong>\u003cstrong>\u003ccode>If I had known, I would have...\u003c/code>\u003c/strong>\u003cstrong>: 과거 사실을 반대로 가정하기\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 현실적인 조건과 비교","depth":2},{"id":"reading-2","label":"2. 핵심 차이","depth":2},{"id":"reading-3","label":"현실적인 미래","depth":3},{"id":"reading-4","label":"비현실적·가상적인 상황","depth":3},{"id":"reading-5","label":"3. 왜 현재 이야기인데 과거형을 쓰나?","depth":2},{"id":"reading-6","label":"4. If I were...","depth":2},{"id":"reading-7","label":"예","depth":2},{"id":"reading-8","label":"5. was도 들리는데?","depth":2},{"id":"reading-9","label":"6. 일반동사","depth":2},{"id":"reading-10","label":"have","depth":3},{"id":"reading-11","label":"know","depth":3},{"id":"reading-12","label":"live","depth":3},{"id":"reading-13","label":"speak","depth":3},{"id":"reading-14","label":"7. 결과절은 would + 동사원형","depth":2},{"id":"reading-15","label":"8. could도 사용할 수 있다","depth":2},{"id":"reading-16","label":"9. might도 가능","depth":2},{"id":"reading-17","label":"10. if절에는 보통 would를 쓰지 않는다","depth":2},{"id":"reading-18","label":"11. 실제 상황을 추론할 수 있다","depth":2},{"id":"reading-19","label":"12. If I were you","depth":2},{"id":"reading-20","label":"13. should와 비교","depth":2},{"id":"reading-21","label":"직접적인 조언","depth":3},{"id":"reading-22","label":"내가 너라면","depth":3},{"id":"reading-23","label":"14. 순서를 바꿀 수 있다","depth":2},{"id":"reading-24","label":"15. 현실 조건문과 가정법 비교","depth":2},{"id":"reading-25","label":"핵심","depth":2},{"id":"reading-26","label":"실제 가능성이 있는 조건","depth":3},{"id":"reading-27","label":"현재와 다른 가정","depth":3},{"id":"reading-28","label":"연습","depth":2}],"origin":"notion","characters":4187,"aliases":{"structure":"concept","examples":"reading-7","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-14","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-18"}},{"id":65,"title":"65단계 — 가정법 과거완료","html":"\u003ch1 id=\"lesson-title\" data-id=\"65\">65단계 — 가정법 과거완료\u003c/h1>\n\u003cp>이번에는 \u003cstrong>이미 끝난 과거를 반대로 가정\u003c/strong>한다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 주어 + had + p.p., 주어 + would have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had known\u003c/strong>, I \u003cstrong>would have helped\u003c/strong> you.\u003cbr>내가 알았더라면 너를 도왔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 사실은 반대다.\u003c/p>\n\u003cblockquote>\n\u003cp>나는 몰랐다.\u003cbr>그래서 도와주지 못했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 가정법 과거와 차이\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">현재 사실과 반대\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had\u003c/strong> more time, I \u003cstrong>would travel\u003c/strong> more.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시간이 더 있다면 여행을 더 많이 할 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>지금 시간이 부족하다는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">과거 사실과 반대\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had had\u003c/strong> more time, I \u003cstrong>would have traveled\u003c/strong> more.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그때 시간이 더 있었더라면 여행을 더 많이 했을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 지나간 과거 이야기다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 기본 구조\u003c/h2>\n\u003cp>조건 부분:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>결과 부분:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If she \u003cstrong>had left\u003c/strong> earlier, she \u003cstrong>would have caught\u003c/strong> the train.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 더 일찍 출발했더라면 기차를 탔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는:\u003c/p>\n\u003cblockquote>\n\u003cp>늦게 출발했다.\u003cbr>기차를 놓쳤다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 왜 \u003ccode>had + p.p.\u003c/code>인가?\u003c/h2>\n\u003cp>이미 배운 과거완료 구조다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>과거의 어떤 시점보다 \u003cstrong>더 이전에 일어난 일\u003c/strong>을 나타낸다.\u003c/p>\n\u003cp>가정법에서는 이것을 이용해서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>이미 지나가서 바꿀 수 없는 과거\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>에 거리를 둔다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 결과는 \u003ccode>would have + p.p.\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I would have gone.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 갔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 실제로는:\u003c/p>\n\u003cblockquote>\n\u003cp>가지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I would go.\u003cbr>갈 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재/미래 가정.\u003c/p>\n\u003cblockquote>\n\u003cp>I would have gone.\u003cbr>갔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거 가정.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 대표 예문\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had studied harder, I would have passed the test.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 더 열심히 공부했더라면 시험에 합격했을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>공부를 충분히 하지 않았다.\u003cbr>시험에 떨어졌다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cblockquote>\n\u003cp>If we had left earlier, we wouldn&#39;t have been late.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리가 더 일찍 출발했더라면 늦지 않았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>늦게 출발했다.\u003cbr>늦었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>had had\u003c/code>도 맞다\u003c/h2>\n\u003cp>처음 보면 이상하지만 문법적으로 완전히 맞다.\u003c/p>\n\u003cp>원래 동사:\u003c/p>\n\u003cblockquote>\n\u003cp>have\u003c/p>\n\u003c/blockquote>\n\u003cp>과거완료:\u003c/p>\n\u003cblockquote>\n\u003cp>had + had\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had had\u003c/strong> enough money, I would have bought it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그때 돈이 충분했더라면 그것을 샀을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>첫 번째 \u003ccode>had\u003c/code>:\u003c/p>\n\u003cblockquote>\n\u003cp>과거완료를 만드는 조동사\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째 \u003ccode>had\u003c/code>:\u003c/p>\n\u003cblockquote>\n\u003cp>have의 과거분사\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. 부정형\u003c/h2>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>hadn&#39;t forgotten\u003c/strong> the key, I could have opened the door.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>열쇠를 잊지 않았더라면 문을 열 수 있었을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>had not\u003c/code>:\u003c/p>\n\u003cblockquote>\n\u003cp>hadn&#39;t\u003c/p>\n\u003c/blockquote>\n\u003cp>결과도 부정 가능:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>wouldn&#39;t have gone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>가지 않았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. \u003ccode>could have + p.p.\u003c/code>\u003c/h2>\n\u003cp>결과절에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 수 있었을 텐데\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미다.\u003c/p>\n\u003cblockquote>\n\u003cp>If I had known earlier, I \u003cstrong>could have helped\u003c/strong> you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>더 일찍 알았더라면 도와줄 수 있었을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">9. \u003ccode>might have + p.p.\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>~했을지도 모른다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If she had left earlier, she \u003cstrong>might have caught\u003c/strong> the train.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 일찍 출발했더라면 기차를 탔을지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 결과절에는:\u003c/p>\n\u003cul>\n\u003cli>\u003cp>would have = ~했을 텐데\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>could have = ~할 수 있었을 텐데\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>might have = ~했을지도 모르는데\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>를 쓸 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">10. 실제 사실과 반대라는 점이 핵심\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had seen him, I would have talked to him.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>그를 봤더라면 이야기했을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>숨겨진 실제 사실:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 그를 \u003cstrong>보지 못했다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>이야기하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">11. 순서를 바꿀 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had known, I would have called you.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>I would have called you if I had known.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 같다.\u003c/p>\n\u003cp>앞에 \u003ccode>if절\u003c/code>이 오면 보통 쉼표를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">12. 가정법 세 단계 비교\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">현실적 미래\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>have\u003c/strong> time, I \u003cstrong>will go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간이 있으면 갈 거야.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">현재와 다른 가정\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had\u003c/strong> time, I \u003cstrong>would go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간이 있다면 갈 텐데.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">과거와 다른 가정\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had had\u003c/strong> time, I \u003cstrong>would have gone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그때 시간이 있었더라면 갔을 텐데.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">한눈에 보기\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">의미\u003c/th>\u003cth scope=\"col\">if절\u003c/th>\u003cth scope=\"col\">결과절\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>현실적 가능성\u003c/td>\u003ctd>현재형\u003c/td>\u003ctd>will + 동사원형\u003c/td>\u003c/tr>\u003ctr>\u003ctd>현재 사실 반대\u003c/td>\u003ctd>과거형\u003c/td>\u003ctd>would + 동사원형\u003c/td>\u003c/tr>\u003ctr>\u003ctd>과거 사실 반대\u003c/td>\u003ctd>had + p.p.\u003c/td>\u003ctd>would have + p.p.\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">핵심\u003c/h2>\n\u003cp>과거 사실을 반대로 가정:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + had + p.p., would have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had known, I would have helped you.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>알았더라면 도왔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제는:\u003c/p>\n\u003cblockquote>\n\u003cp>몰랐고, 그래서 돕지 못했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>If I \u003cstrong>had known / knew\u003c/strong>, I would have called you.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If she had studied harder, she \u003cstrong>would pass / would have passed\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If we \u003cstrong>had left / left\u003c/strong> earlier, we wouldn&#39;t have been late.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I had had enough money, I \u003cstrong>would have bought / would buy\u003c/strong> it.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If he had asked me, I \u003cstrong>could have helped / could help\u003c/strong> him.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“그때 알았더라면 가지 않았을 텐데.”\u003c/p>\n\u003cp> → If I had known, I \u003cstrong>wouldn&#39;t have gone / wouldn&#39;t go\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>66단계 — 혼합가정법: 과거의 일이 현재 결과에 영향을 주는 구조\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 가정법 과거와 차이","depth":2},{"id":"reading-2","label":"현재 사실과 반대","depth":3},{"id":"reading-3","label":"과거 사실과 반대","depth":3},{"id":"reading-4","label":"2. 기본 구조","depth":2},{"id":"reading-5","label":"3. 왜 had + p.p.인가?","depth":2},{"id":"reading-6","label":"4. 결과는 would have + p.p.","depth":2},{"id":"reading-7","label":"비교","depth":2},{"id":"reading-8","label":"5. 대표 예문","depth":2},{"id":"reading-9","label":"6. had had도 맞다","depth":2},{"id":"reading-10","label":"7. 부정형","depth":2},{"id":"reading-11","label":"8. could have + p.p.","depth":2},{"id":"reading-12","label":"9. might have + p.p.","depth":2},{"id":"reading-13","label":"10. 실제 사실과 반대라는 점이 핵심","depth":2},{"id":"reading-14","label":"11. 순서를 바꿀 수도 있다","depth":2},{"id":"reading-15","label":"12. 가정법 세 단계 비교","depth":2},{"id":"reading-16","label":"현실적 미래","depth":3},{"id":"reading-17","label":"현재와 다른 가정","depth":3},{"id":"reading-18","label":"과거와 다른 가정","depth":3},{"id":"reading-19","label":"한눈에 보기","depth":2},{"id":"reading-20","label":"핵심","depth":2},{"id":"reading-21","label":"연습","depth":2}],"origin":"notion","characters":3515,"aliases":{"structure":"reading-4","examples":"reading-8","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-14"}},{"id":66,"title":"66단계 — 혼합가정법","html":"\u003ch1 id=\"lesson-title\" data-id=\"66\">66단계 — 혼합가정법\u003c/h1>\n\u003cp>혼합가정법은 이름 그대로 \u003cstrong>과거 조건과 현재 결과를 섞는 구조\u003c/strong>다.\u003c/p>\n\u003cp>가장 중요한 형태는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + had + p.p., would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거에 ~했더라면, 지금은 ~할 텐데\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 예문\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had studied harder, I would have a better job now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 예전에 더 열심히 공부했더라면, 지금 더 좋은 직업을 가지고 있을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간을 나눠보면:\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">과거 원인\u003c/h3>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had studied\u003c/strong> harder\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">현재 결과\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>would have\u003c/strong> a better job now\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>과거 ───────→ 현재\u003c/p>\n\u003c/blockquote>\n\u003cp>과거의 일이 현재 상태에 영향을 주고 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 가정법 과거완료와 비교\u003c/h2>\n\u003cp>이전 단계:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had studied harder, I \u003cstrong>would have passed\u003c/strong> the test.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>더 열심히 공부했더라면 시험에 합격했을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거 조건 + 과거 결과다.\u003c/p>\n\u003cblockquote>\n\u003cp>과거 → 과거\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cp>혼합가정법:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had studied harder, I \u003cstrong>would know\u003c/strong> more now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>더 열심히 공부했더라면 지금 더 많이 알고 있을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>과거 → 현재\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 구조 비교\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">과거 → 과거\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + had p.p., would have p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I had left earlier, I would have arrived on time.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">과거 → 현재\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + had p.p., would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I had left that job, I would be happier now.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. 실제 사실은 반대\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had exercised regularly, I would be healthier now.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>예전에 꾸준히 운동했더라면 지금 더 건강할 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 상황:\u003c/p>\n\u003cblockquote>\n\u003cp>과거에 꾸준히 운동하지 않았다.\u003cbr>지금 그 결과가 남아 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>would be\u003c/code>가 많이 나온다\u003c/h2>\n\u003cp>현재의 \u003cstrong>상태\u003c/strong>를 말하는 경우가 많기 때문이다.\u003c/p>\n\u003cblockquote>\n\u003cp>If I had gone to bed earlier, I \u003cstrong>wouldn&#39;t be tired now\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어젯밤 더 일찍 잤더라면 지금 피곤하지 않을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거:\u003c/p>\n\u003cblockquote>\n\u003cp>늦게 잤다.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재:\u003c/p>\n\u003cblockquote>\n\u003cp>피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>could\u003c/code>도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>If I had studied English when I was younger, I \u003cstrong>could speak\u003c/strong> it better now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어릴 때 영어를 공부했더라면 지금 영어를 더 잘할 수 있을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>could speak = 지금 할 수 있을 텐데\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. 반대 방향의 혼합도 있다\u003c/h2>\n\u003cp>조금 덜 흔하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>현재 상태 때문에 과거 결과가 달라졌을 것\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 말할 수도 있다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 과거형, would have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I were more organized, I wouldn&#39;t have missed the meeting yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 좀 더 체계적인 사람이었다면 어제 회의를 놓치지 않았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">현재 상태\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m not very organized.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">과거 결과\u003c/h3>\n\u003cblockquote>\n\u003cp>I missed the meeting yesterday.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 두 종류\u003c/h2>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">① 과거 원인 → 현재 결과\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + had p.p., would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I had taken that job, I would live in Seoul now.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">② 현재 상태 → 과거 결과\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 과거형, would have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I were more careful, I wouldn&#39;t have made that mistake.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째 유형은 상대적으로 덜 자주 나온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. 시간 표현이 힌트가 된다\u003c/h2>\n\u003cp>혼합가정법에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>now\u003cbr>today\u003cbr>currently\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 표현이 현재 결과를 보여주는 경우가 많다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had slept more, I wouldn&#39;t be tired \u003cstrong>now\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>yesterday\u003cbr>last night\u003cbr>then\u003c/p>\n\u003c/blockquote>\n\u003cp>이면 과거 결과일 가능성이 높다.\u003c/p>\n\u003cblockquote>\n\u003cp>If I had slept more, I wouldn&#39;t have fallen asleep at work \u003cstrong>yesterday\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. 세 가지 비교\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">현재 사실 반대\u003c/h3>\n\u003cblockquote>\n\u003cp>If I had more money, I would buy a house.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 돈이 더 있다면 집을 살 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">과거 사실 반대\u003c/h3>\n\u003cblockquote>\n\u003cp>If I had had more money, I would have bought a house.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그때 돈이 더 있었더라면 집을 샀을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">과거 → 현재\u003c/h3>\n\u003cblockquote>\n\u003cp>If I had bought that house, I would live there now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그 집을 샀더라면 지금 거기 살고 있을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">핵심\u003c/h2>\n\u003cp>가장 중요한 혼합가정법:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + had + p.p., would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거가 달랐더라면 지금은 달랐을 텐데\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I had studied English earlier, I would speak it better now.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>If I had gone to bed earlier, I \u003cstrong>wouldn&#39;t be / wouldn&#39;t have been\u003c/strong> tired now.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I had studied harder, I \u003cstrong>would know / would have known\u003c/strong> more now.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If she had taken that job, she \u003cstrong>would live / would have lived\u003c/strong> in Seoul now.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I were more careful, I \u003cstrong>wouldn&#39;t have made / wouldn&#39;t make\u003c/strong> that mistake yesterday.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I had exercised regularly, I \u003cstrong>would be / would have been\u003c/strong> healthier now.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>67단계 — 과거완료 \u003c/strong>\u003cstrong>\u003ccode>had + p.p.\u003c/code>\u003c/strong>\u003cstrong> 자체를 가정법이 아닌 일반 시제로 정확히 구분하기\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 예문","depth":2},{"id":"reading-2","label":"과거 원인","depth":3},{"id":"reading-3","label":"현재 결과","depth":3},{"id":"reading-4","label":"2. 가정법 과거완료와 비교","depth":2},{"id":"reading-5","label":"3. 구조 비교","depth":2},{"id":"reading-6","label":"과거 → 과거","depth":3},{"id":"reading-7","label":"과거 → 현재","depth":3},{"id":"reading-8","label":"4. 실제 사실은 반대","depth":2},{"id":"reading-9","label":"5. would be가 많이 나온다","depth":2},{"id":"reading-10","label":"6. could도 가능","depth":2},{"id":"reading-11","label":"7. 반대 방향의 혼합도 있다","depth":2},{"id":"reading-12","label":"현재 상태","depth":3},{"id":"reading-13","label":"과거 결과","depth":3},{"id":"reading-14","label":"8. 두 종류","depth":2},{"id":"reading-15","label":"① 과거 원인 → 현재 결과","depth":2},{"id":"reading-16","label":"② 현재 상태 → 과거 결과","depth":2},{"id":"reading-17","label":"9. 시간 표현이 힌트가 된다","depth":2},{"id":"reading-18","label":"10. 세 가지 비교","depth":2},{"id":"reading-19","label":"현재 사실 반대","depth":3},{"id":"reading-20","label":"과거 사실 반대","depth":3},{"id":"reading-21","label":"과거 → 현재","depth":3},{"id":"reading-22","label":"핵심","depth":2},{"id":"reading-23","label":"연습","depth":2}],"origin":"notion","characters":3197,"aliases":{"structure":"reading-5","examples":"reading-1","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-8","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-14","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-18"}},{"id":67,"title":"67단계 — 과거완료","html":"\u003ch1 id=\"lesson-title\" data-id=\"67\">67단계 — 과거완료\u003c/h1>\n\u003cp>이번에는 가정법이 아니라 \u003cstrong>일반 시제로서의 과거완료\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거의 두 사건 중 더 먼저 일어난 일을 표시\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하는 것이다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had + 과거분사(p.p.)\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 과거시제만으로도 말할 수 있는데 왜 과거완료가 필요한가?\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I arrived at the station.\u003cbr>The train left.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 과거다.\u003c/p>\n\u003cp>그런데 실제 순서가:\u003c/p>\n\u003cblockquote>\n\u003cp>기차 출발 → 내가 역에 도착\u003c/p>\n\u003c/blockquote>\n\u003cp>이라면 이 관계를 명확하게 보여주기 위해 과거완료를 쓸 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>The train \u003cstrong>had left\u003c/strong> before I arrived at the station.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 역에 도착하기 전에 기차는 이미 떠난 뒤였다.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간 순서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had left\u003c/strong> → arrived → 현재\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 기본 구조\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">더 먼저 일어난 과거\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">그다음 일어난 과거\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>had finished\u003c/strong> dinner before I \u003cstrong>called\u003c/strong> her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 그녀에게 전화하기 전에 그녀는 이미 저녁을 다 먹었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 주어가 누구든 \u003ccode>had\u003c/code>\u003c/h2>\n\u003cp>현재완료는:\u003c/p>\n\u003cblockquote>\n\u003cp>I have eaten.\u003cbr>She has eaten.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어에 따라 \u003ccode>have / has\u003c/code>가 달랐다.\u003c/p>\n\u003cp>하지만 과거완료는 전부:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I had eaten.\u003cbr>She had eaten.\u003cbr>They had eaten.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 과거시제와 비교\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">과거시제\u003c/h3>\n\u003cblockquote>\n\u003cp>I ate dinner at 7.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 7시에 저녁을 먹었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그냥 과거 사건 하나.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">과거완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I had eaten dinner before she arrived.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 도착하기 전에 나는 이미 저녁을 먹은 상태였다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>had eaten\u003c/code>은 다른 과거 사건인 \u003ccode>arrived\u003c/code>보다 더 앞선다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>before\u003c/code>\u003c/h2>\n\u003cp>과거완료와 아주 잘 어울린다.\u003c/p>\n\u003cblockquote>\n\u003cp>I had finished work \u003cstrong>before\u003c/strong> he called me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 전화하기 전에 나는 일을 끝낸 상태였다.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 \u003ccode>before\u003c/code> 자체가 순서를 명확히 보여주기 때문에 실제 영어에서는 과거시제만 쓰기도 한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I finished work before he called me.\u003c/p>\n\u003c/blockquote>\n\u003cp>이것도 자연스럽다.\u003c/p>\n\u003cp>즉 과거완료는 특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>먼저 일어난 과거를 강조하거나 순서를 분명하게 할 때\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>유용하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>after\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>After I \u003cstrong>had finished\u003c/strong> work, I went home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일을 끝낸 후 집에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>순서:\u003c/p>\n\u003cblockquote>\n\u003cp>had finished → went\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 역시:\u003c/p>\n\u003cblockquote>\n\u003cp>After I finished work, I went home.\u003c/p>\n\u003c/blockquote>\n\u003cp>도 매우 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. \u003ccode>already\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>The movie \u003cstrong>had already started\u003c/strong> when we arrived.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리가 도착했을 때 영화는 이미 시작한 뒤였다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>already\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>이미\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이라 과거완료와 자주 쓰인다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>when\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>When I got home, my daughter \u003cstrong>had already fallen asleep\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 집에 도착했을 때 딸은 이미 잠든 뒤였다.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간 순서:\u003c/p>\n\u003col>\n\u003cli>\u003cp>딸이 잠듦\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>내가 집에 도착함\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>had fallen asleep\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. 부정문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>had not + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>hadn&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>hadn&#39;t eaten\u003c/strong> before the meeting started.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>회의가 시작되기 전에 나는 아무것도 먹지 않은 상태였다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">10. 의문문\u003c/h2>\n\u003cp>\u003ccode>had\u003c/code>를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Had you eaten\u003c/strong> before you left?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>떠나기 전에 먹었어?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Had + 주어 + p.p.?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">11. \u003ccode>did\u003c/code>를 쓰지 않는다\u003c/h2>\n\u003cp>과거완료에는 이미 \u003ccode>had\u003c/code>가 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Did you had eaten?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ Did you have eaten?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ Had you eaten?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">12. 과거완료와 현재완료 비교\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have finished\u003c/strong> my work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일을 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003cp>기준점:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>현재\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 과거의 일이 지금과 연결된다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">과거완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>had finished\u003c/strong> my work before he arrived.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 도착하기 전에 나는 일을 끝낸 상태였다.\u003c/p>\n\u003c/blockquote>\n\u003cp>기준점:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거의 다른 시점\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>현재완료 = \u003cstrong>과거 → 현재\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>과거완료 = \u003cstrong>더 과거 → 과거\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">13. 시간선으로 보면\u003c/h2>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I have eaten.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>먹음 ─────────→ 지금\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">과거완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I had eaten before she came.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>먹음 → 그녀가 옴 ─────→ 지금\u003c/strong>\u003c/p>\n\u003cp>\u003ccode>had eaten\u003c/code>이 더 왼쪽이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">14. 과거완료와 가정법 과거완료는 모양이 같다\u003c/h2>\n\u003cp>이전 단계와 연결된다.\u003c/p>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">일반 과거완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I had left before he arrived.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 도착하기 전에 나는 떠났다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 일어난 일이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">가정법 과거완료\u003c/h3>\n\u003cblockquote>\n\u003cp>If I had left earlier, I would have caught the train.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>더 일찍 떠났더라면 기차를 탔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는:\u003c/p>\n\u003cblockquote>\n\u003cp>일찍 떠나지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">어떻게 구분하나?\u003c/h2>\n\u003cp>\u003cstrong>문장 의미와 구조\u003c/strong>를 본다.\u003c/p>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">실제 과거 사건\u003c/h3>\n\u003cblockquote>\n\u003cp>She had eaten before I arrived.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">사실과 반대되는 가정\u003c/h3>\n\u003cblockquote>\n\u003cp>If she had eaten, she wouldn&#39;t have been hungry.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>had + p.p.\u003c/code> 모양만 보고 가정법이라고 판단하면 안 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">15. 간접화법에서도 자주 나온다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cp>직접 말:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;I lost my key.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>나중에 전달:\u003c/p>\n\u003cblockquote>\n\u003cp>He said that he \u003cstrong>had lost\u003c/strong> his key.\u003c/p>\n\u003c/blockquote>\n\u003cp>말한 시점보다 열쇠를 잃어버린 것이 더 이전이기 때문에 과거완료가 쓰일 수 있다.\u003c/p>\n\u003cp>이건 뒤에서 \u003cstrong>간접화법\u003c/strong> 단계에서 자세히 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">핵심\u003c/h2>\n\u003cp>과거완료:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>의미:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거의 기준 시점보다 더 먼저 일어난 일\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The train \u003cstrong>had left\u003c/strong> before I arrived.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간 순서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had left → arrived → 현재\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 꼭 구분:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/has + p.p. = 현재완료\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>had + p.p. = 과거완료\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-30\" data-reading-anchor=\"reading-30\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>The train \u003cstrong>had left / has left\u003c/strong> before I arrived.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>had finished / finished\u003c/strong> dinner before I called her.\u003c/p>\n\u003cp> → 먼저 끝냈다는 점을 강조\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>When I got home, my daughter \u003cstrong>had already fallen / has already fallen\u003c/strong> asleep.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>hadn&#39;t eaten / didn&#39;t had eaten\u003c/strong> before the meeting.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Had you finished / Did you had finished\u003c/strong> the work before he came?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>If I had known, I would have called you.\u003c/code>의 \u003ccode>had known\u003c/code>은 \u003cstrong>일반 과거완료 / 가정법 과거완료\u003c/strong> 중 무엇인지 생각해봐.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>68단계 — 간접화법 \u003c/strong>\u003cstrong>\u003ccode>He said that...\u003c/code>\u003c/strong>\u003cstrong>: 시제 일치와 \u003c/strong>\u003cstrong>\u003ccode>said / told\u003c/code>\u003c/strong>\u003cstrong> 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 과거시제만으로도 말할 수 있는데 왜 과거완료가 필요한가?","depth":2},{"id":"reading-2","label":"2. 기본 구조","depth":2},{"id":"reading-3","label":"더 먼저 일어난 과거","depth":3},{"id":"reading-4","label":"그다음 일어난 과거","depth":3},{"id":"reading-5","label":"3. 주어가 누구든 had","depth":2},{"id":"reading-6","label":"4. 과거시제와 비교","depth":2},{"id":"reading-7","label":"과거시제","depth":3},{"id":"reading-8","label":"과거완료","depth":3},{"id":"reading-9","label":"5. before","depth":2},{"id":"reading-10","label":"6. after","depth":2},{"id":"reading-11","label":"7. already","depth":2},{"id":"reading-12","label":"8. when","depth":2},{"id":"reading-13","label":"9. 부정문","depth":2},{"id":"reading-14","label":"10. 의문문","depth":2},{"id":"reading-15","label":"11. did를 쓰지 않는다","depth":2},{"id":"reading-16","label":"12. 과거완료와 현재완료 비교","depth":2},{"id":"reading-17","label":"현재완료","depth":3},{"id":"reading-18","label":"과거완료","depth":3},{"id":"reading-19","label":"13. 시간선으로 보면","depth":2},{"id":"reading-20","label":"현재완료","depth":3},{"id":"reading-21","label":"과거완료","depth":3},{"id":"reading-22","label":"14. 과거완료와 가정법 과거완료는 모양이 같다","depth":2},{"id":"reading-23","label":"일반 과거완료","depth":3},{"id":"reading-24","label":"가정법 과거완료","depth":3},{"id":"reading-25","label":"어떻게 구분하나?","depth":2},{"id":"reading-26","label":"실제 과거 사건","depth":3},{"id":"reading-27","label":"사실과 반대되는 가정","depth":3},{"id":"reading-28","label":"15. 간접화법에서도 자주 나온다","depth":2},{"id":"reading-29","label":"핵심","depth":2},{"id":"reading-30","label":"연습","depth":2}],"origin":"notion","characters":3853,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-6","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-16"}},{"id":68,"title":"68단계 — 간접화법","html":"\u003ch1 id=\"lesson-title\" data-id=\"68\">68단계 — 간접화법\u003c/h1>\n\u003cp>이번에는 \u003cstrong>누군가 한 말을 다른 사람에게 전달하는 방법\u003c/strong>을 배운다.\u003c/p>\n\u003cp>핵심은 두 가지다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>said + (that) + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>told + 사람 + (that) + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 직접화법과 간접화법\u003c/h2>\n\u003cp>직접 말한 내용을 그대로 옮기면:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom said, \u003cstrong>&quot;I am tired.&quot;\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>간접화법으로 바꾸면:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom said \u003cstrong>that he was tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>톰은 자신이 피곤하다고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>said\u003c/code>와 \u003ccode>told\u003c/code> 차이\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">said\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>said + 내용\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He said \u003cstrong>that he was tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 바로 뒤에 사람을 두지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ He said me that he was tired.\u003cbr>✅ He said that he was tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">told\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>told + 사람 + 내용\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He told \u003cstrong>me\u003c/strong> that he was tired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 나에게 자신이 피곤하다고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ He told that he was tired.\u003cbr>✅ He told me that he was tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 기본 구조\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">say\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>say + something\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">tell\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>tell + someone + something\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She said, &quot;I&#39;m busy.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>She said \u003cstrong>that she was busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>She told \u003cstrong>me\u003c/strong> that she was busy.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. \u003ccode>that\u003c/code>은 자주 생략한다\u003c/h2>\n\u003cblockquote>\n\u003cp>He said \u003cstrong>that he was tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>=\u003c/p>\n\u003cblockquote>\n\u003cp>He said \u003cstrong>he was tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>회화에서는 \u003ccode>that\u003c/code>을 자주 생략한다.\u003c/p>\n\u003cp>마찬가지:\u003c/p>\n\u003cblockquote>\n\u003cp>She told me \u003cstrong>she was busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. 시제 일치\u003c/h2>\n\u003cp>말을 전달하는 동사가 과거형이면:\u003c/p>\n\u003cblockquote>\n\u003cp>said\u003cbr>told\u003c/p>\n\u003c/blockquote>\n\u003cp>뒤의 시제가 \u003cstrong>한 단계 과거로 이동하는 경우가 많다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">현재 → 과거\u003c/h2>\n\u003cp>직접화법:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;I \u003cstrong>am\u003c/strong> tired.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>간접화법:\u003c/p>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>was\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>&quot;I \u003cstrong>work\u003c/strong> here.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>worked\u003c/strong> there.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">현재진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>&quot;I \u003cstrong>am working\u003c/strong>.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>was working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">6. 과거 → 과거완료\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;I \u003cstrong>lost\u003c/strong> my key.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>had lost\u003c/strong> his key.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간 순서:\u003c/p>\n\u003cblockquote>\n\u003cp>열쇠를 잃음 → 그 말을 함 → 지금 전달\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서 \u003ccode>lost\u003c/code>보다 더 이전 사건임을 보여주기 위해:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had lost\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 사용할 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. 현재완료 → 과거완료\u003c/h2>\n\u003cblockquote>\n\u003cp>&quot;I \u003cstrong>have finished\u003c/strong> the work.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>She said she \u003cstrong>had finished\u003c/strong> the work.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>have/has + p.p.\u003cbr>↓\u003cbr>had + p.p.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. \u003ccode>will → would\u003c/code>\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;I \u003cstrong>will call\u003c/strong> you.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>He said he \u003cstrong>would call\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에서 배운 \u003ccode>would = 과거에서 바라본 미래\u003c/code>가 바로 여기서 나온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">9. \u003ccode>can → could\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>&quot;I \u003cstrong>can help\u003c/strong> you.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>She said she \u003cstrong>could help\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">10. 기본 시제 변화\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">직접화법\u003c/th>\u003cth scope=\"col\">간접화법\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>am/is\u003c/td>\u003ctd>was\u003c/td>\u003c/tr>\u003ctr>\u003ctd>are\u003c/td>\u003ctd>were\u003c/td>\u003c/tr>\u003ctr>\u003ctd>work\u003c/td>\u003ctd>worked\u003c/td>\u003c/tr>\u003ctr>\u003ctd>am working\u003c/td>\u003ctd>was working\u003c/td>\u003c/tr>\u003ctr>\u003ctd>worked\u003c/td>\u003ctd>had worked\u003c/td>\u003c/tr>\u003ctr>\u003ctd>have worked\u003c/td>\u003ctd>had worked\u003c/td>\u003c/tr>\u003ctr>\u003ctd>will\u003c/td>\u003ctd>would\u003c/td>\u003c/tr>\u003ctr>\u003ctd>can\u003c/td>\u003ctd>could\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. 대명사도 바뀐다\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom said, &quot;\u003cstrong>I\u003c/strong> like \u003cstrong>my\u003c/strong> job.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>Tom이 말했으므로:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom said \u003cstrong>he\u003c/strong> liked \u003cstrong>his\u003c/strong> job.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 말하는 사람이 바뀌면:\u003c/p>\n\u003cblockquote>\n\u003cp>I → he/she\u003cbr>my → his/her\u003cbr>me → him/her\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 상황에 맞게 바꾼다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">12. 시간·장소 표현도 바뀔 수 있다\u003c/h2>\n\u003cp>말을 나중에 다른 장소에서 전달하면 표현도 달라질 수 있다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">직접화법\u003c/th>\u003cth scope=\"col\">간접화법에서 흔한 변화\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>now\u003c/td>\u003ctd>then\u003c/td>\u003c/tr>\u003ctr>\u003ctd>today\u003c/td>\u003ctd>that day\u003c/td>\u003c/tr>\u003ctr>\u003ctd>yesterday\u003c/td>\u003ctd>the day before\u003c/td>\u003c/tr>\u003ctr>\u003ctd>tomorrow\u003c/td>\u003ctd>the next day\u003c/td>\u003c/tr>\u003ctr>\u003ctd>here\u003c/td>\u003ctd>there\u003c/td>\u003c/tr>\u003ctr>\u003ctd>this\u003c/td>\u003ctd>that\u003c/td>\u003c/tr>\u003ctr>\u003ctd>these\u003c/td>\u003ctd>those\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;I&#39;ll finish it \u003cstrong>tomorrow\u003c/strong>.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>He said he would finish it \u003cstrong>the next day\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">13. 항상 시제를 바꿔야 하는 것은 아니다\u003c/h2>\n\u003cp>이 부분이 중요하다.\u003c/p>\n\u003cp>현재도 여전히 사실이라면 현재형을 유지할 수도 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The teacher said, &quot;Water boils at 100°C.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>전달:\u003c/p>\n\u003cblockquote>\n\u003cp>The teacher said that water \u003cstrong>boils\u003c/strong> at 100°C.\u003c/p>\n\u003c/blockquote>\n\u003cp>일반적인 사실이므로 굳이:\u003c/p>\n\u003cblockquote>\n\u003cp>boiled\u003c/p>\n\u003c/blockquote>\n\u003cp>로 바꿀 필요가 없다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">14. 말한 내용이 지금도 사실일 때\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Mina said, &quot;I live in Busan.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>그녀가 지금도 부산에 산다면:\u003c/p>\n\u003cblockquote>\n\u003cp>Mina said she \u003cstrong>lives\u003c/strong> in Busan.\u003c/p>\n\u003c/blockquote>\n\u003cp>도 가능하다.\u003c/p>\n\u003cp>과거 당시 상황만 전달하면:\u003c/p>\n\u003cblockquote>\n\u003cp>Mina said she \u003cstrong>lived\u003c/strong> in Busan.\u003c/p>\n\u003c/blockquote>\n\u003cp>도 가능하다.\u003c/p>\n\u003cp>즉 시제 일치는 \u003cstrong>기계적인 절대 규칙은 아니다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">15. \u003ccode>say to\u003c/code>와 \u003ccode>tell\u003c/code>\u003c/h2>\n\u003cp>사람을 넣고 싶으면:\u003c/p>\n\u003cblockquote>\n\u003cp>He said \u003cstrong>to me\u003c/strong>, &quot;...&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>도 가능하다.\u003c/p>\n\u003cp>하지만 간접화법에서는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>told me\u003c/strong> that...\u003c/p>\n\u003c/blockquote>\n\u003cp>가 더 자연스럽다.\u003c/p>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>He said to me, &quot;Be careful.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He told me to be careful.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">16. 명령문은 \u003ccode>tell + 사람 + to do\u003c/code>\u003c/h2>\n\u003cp>앞에서 배운 구조와 연결된다.\u003c/p>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;Sit down.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>He told me \u003cstrong>to sit down\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">하지 말라는 명령\u003c/h3>\n\u003cblockquote>\n\u003cp>&quot;Don&#39;t touch it.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>He told me \u003cstrong>not to touch it\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>tell + 사람 + not to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">17. 질문을 전달할 때\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;Where do you live?&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>He asked me \u003cstrong>where I lived\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ where did I live\u003cbr>✅ where I lived\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에서 배운 \u003cstrong>간접의문문 어순\u003c/strong>을 그대로 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">18. Yes/No 질문\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;Do you like coffee?&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>He asked me \u003cstrong>if I liked coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>He asked me \u003cstrong>whether I liked coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>ask + 사람 + if/whether + 평서문 어순\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">핵심\u003c/h2>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">말한 내용 전달\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>said + (that) + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He said he was tired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-29\" data-reading-anchor=\"reading-29\">누구에게 말했는지 포함\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>told + 사람 + (that) + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He told me he was tired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-30\" data-reading-anchor=\"reading-30\">명령\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>told + 사람 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He told me to wait.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">질문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>asked + 사람 + 의문사/if + 평서문 어순\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He asked me where I lived.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-32\" data-reading-anchor=\"reading-32\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>He \u003cstrong>said me / told me\u003c/strong> that he was tired.\u003c/p>\n\u003cp> → 둘 중 \u003ccode>me\u003c/code>와 함께 쓸 수 있는 것\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She said she \u003cstrong>is / was\u003c/strong> busy.\u003c/p>\n\u003cp> → 당시 상황을 과거로 전달\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He said he \u003cstrong>will / would\u003c/strong> call me.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She told \u003cstrong>me to wait / to me wait\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He asked me \u003cstrong>where I lived / where did I live\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She asked me \u003cstrong>if I liked / did I like\u003c/strong> coffee.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>69단계 — \u003c/strong>\u003cstrong>\u003ccode>have/get something done\u003c/code>\u003c/strong>\u003cstrong>: “내가 직접 한 것이 아니라 남에게 시켜서 받는 것”\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 직접화법과 간접화법","depth":2},{"id":"reading-2","label":"2. said와 told 차이","depth":2},{"id":"reading-3","label":"said","depth":3},{"id":"reading-4","label":"told","depth":3},{"id":"reading-5","label":"3. 기본 구조","depth":2},{"id":"reading-6","label":"say","depth":3},{"id":"reading-7","label":"tell","depth":3},{"id":"reading-8","label":"4. that은 자주 생략한다","depth":2},{"id":"reading-9","label":"5. 시제 일치","depth":2},{"id":"reading-10","label":"현재 → 과거","depth":2},{"id":"reading-11","label":"일반동사","depth":3},{"id":"reading-12","label":"현재진행형","depth":3},{"id":"reading-13","label":"6. 과거 → 과거완료","depth":2},{"id":"reading-14","label":"7. 현재완료 → 과거완료","depth":2},{"id":"reading-15","label":"8. will → would","depth":2},{"id":"reading-16","label":"9. can → could","depth":2},{"id":"reading-17","label":"10. 기본 시제 변화","depth":2},{"id":"reading-18","label":"11. 대명사도 바뀐다","depth":2},{"id":"reading-19","label":"12. 시간·장소 표현도 바뀔 수 있다","depth":2},{"id":"reading-20","label":"13. 항상 시제를 바꿔야 하는 것은 아니다","depth":2},{"id":"reading-21","label":"14. 말한 내용이 지금도 사실일 때","depth":2},{"id":"reading-22","label":"15. say to와 tell","depth":2},{"id":"reading-23","label":"16. 명령문은 tell + 사람 + to do","depth":2},{"id":"reading-24","label":"하지 말라는 명령","depth":3},{"id":"reading-25","label":"17. 질문을 전달할 때","depth":2},{"id":"reading-26","label":"18. Yes/No 질문","depth":2},{"id":"reading-27","label":"핵심","depth":2},{"id":"reading-28","label":"말한 내용 전달","depth":3},{"id":"reading-29","label":"누구에게 말했는지 포함","depth":3},{"id":"reading-30","label":"명령","depth":3},{"id":"reading-31","label":"질문","depth":3},{"id":"reading-32","label":"연습","depth":2}],"origin":"notion","characters":4785,"aliases":{"structure":"reading-5","examples":"concept","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-8","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-18"}},{"id":69,"title":"69단계 — have/get something done","html":"\u003ch1 id=\"lesson-title\" data-id=\"69\">69단계 — have/get something done\u003c/h1>\n\u003cp>이번에는 \u003cstrong>내가 직접 하는 게 아니라, 다른 사람에게 맡겨서 어떤 일을 받는 구조\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 목적어 + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>get + 목적어 + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~을 맡겨서 하게 하다 / ~을 해두다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 예문\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>had my car repaired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차를 수리했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 정확한 의미는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>내가 직접 수리한 게 아니라, 정비소 등에 맡겨 수리받았다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + have + 사물 + 과거분사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I had \u003cstrong>my car\u003c/strong> \u003cstrong>repaired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003cp>I = 일을 맡긴 사람\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>had = 시킴/받음\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>my car = 작업 대상\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>repaired = 수리된\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>내 차가 수리되도록 했다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 직접 한 것과 비교\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">내가 직접 수리\u003c/h3>\n\u003cblockquote>\n\u003cp>I repaired my car.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 직접 차를 수리했다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">남에게 맡겨 수리\u003c/h3>\n\u003cblockquote>\n\u003cp>I had my car repaired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>차를 수리받았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 차이가 핵심이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 자주 쓰는 예\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">머리 자르기\u003c/h3>\n\u003cblockquote>\n\u003cp>I had my hair cut.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>머리를 잘랐다.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 본인이 직접 자른 게 아니라 미용실에서 잘랐다는 뜻이다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I cut my hair.\u003c/p>\n\u003c/blockquote>\n\u003cp>는 문맥에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>내가 직접 내 머리를 잘랐다\u003c/p>\n\u003c/blockquote>\n\u003cp>는 뜻으로 이해될 수 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">치아 검사\u003c/h3>\n\u003cblockquote>\n\u003cp>I had my teeth checked.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>치아 검사를 받았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">집 청소\u003c/h3>\n\u003cblockquote>\n\u003cp>I had my house cleaned.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>집을 청소하게 했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">컴퓨터 수리\u003c/h3>\n\u003cblockquote>\n\u003cp>I had my computer repaired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>컴퓨터를 수리받았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">5. \u003ccode>get something done\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>get\u003c/code>도 같은 구조로 많이 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>got my phone fixed\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>휴대폰을 수리받았다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>got my hair cut\u003c/strong> yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어제 머리를 잘랐다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>get\u003c/code>은 회화에서 매우 흔하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. \u003ccode>have\u003c/code>와 \u003ccode>get\u003c/code> 차이\u003c/h2>\n\u003cp>의미는 상당히 비슷하다.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">have\u003c/h3>\n\u003cblockquote>\n\u003cp>I had my car repaired.\u003c/p>\n\u003c/blockquote>\n\u003cp>조금 더 중립적.\u003c/p>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">get\u003c/h3>\n\u003cblockquote>\n\u003cp>I got my car repaired.\u003c/p>\n\u003c/blockquote>\n\u003cp>회화에서 조금 더 자연스럽고 구어적인 경우가 많다.\u003c/p>\n\u003cp>초급에서는 둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>남에게 맡겨서 어떤 일을 받다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>로 이해하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">7. 시제는 \u003ccode>have/get\u003c/code>이 바뀐다\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have\u003c/strong> my car washed every week.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>매주 차를 세차 맡긴다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">과거\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>had\u003c/strong> my car washed yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어제 차를 세차했다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">미래\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will have\u003c/strong> my car washed tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일 차를 세차할 것이다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have had\u003c/strong> my car repaired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>차를 수리받았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 첫 번째 \u003ccode>have\u003c/code>는 현재완료를 만드는 조동사이고, 두 번째 \u003ccode>had\u003c/code>는 본동사 \u003ccode>have\u003c/code>의 과거분사다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">8. \u003ccode>get\u003c/code>도 시제 변화\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>get\u003c/strong> my hair cut every month.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>got\u003c/strong> my hair cut yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ll \u003cstrong>get\u003c/strong> my hair cut tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">9. 사역동사 \u003ccode>have + 사람 + 동사원형\u003c/code>과 비교\u003c/h2>\n\u003cp>앞에서 배운:\u003c/p>\n\u003cblockquote>\n\u003cp>I had him \u003cstrong>check\u003c/strong> the file.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>내가 그에게 파일을 확인하게 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cp>이번 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>I had the file \u003cstrong>checked\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>파일을 확인받았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 사물 + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 사람 + do\u003c/strong>\u003cbr>사람에게 일을 시킴\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 사물 + done\u003c/strong>\u003cbr>사물이 어떤 처리를 받게 함\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">10. 비교하면 확실하다\u003c/h2>\n\u003cblockquote>\n\u003cp>I had the mechanic \u003cstrong>repair my car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 정비사에게 내 차를 수리하게 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>mechanic = 사람\u003cbr>repair = 동사원형\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cblockquote>\n\u003cp>I had my car \u003cstrong>repaired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차를 수리받았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>my car = 사물\u003cbr>repaired = p.p.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">11. 원치 않은 일을 당했을 때도 사용 가능\u003c/h2>\n\u003cp>이 구조는 항상 내가 일부러 맡겼다는 뜻만 있는 건 아니다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>had my wallet stolen\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지갑을 도난당했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>내가 도둑에게:\u003c/p>\n\u003cblockquote>\n\u003cp>“지갑을 훔쳐주세요.”\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 시킨 게 아니다.\u003c/p>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>내 소유물에 원치 않는 일이 발생했다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 의미다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">또 다른 예\u003c/h3>\n\u003cblockquote>\n\u003cp>She had her phone stolen.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 휴대폰을 도난당했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 문맥에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>맡겨서 서비스를 받음\u003c/p>\n\u003c/blockquote>\n\u003cp>또는\u003c/p>\n\u003cblockquote>\n\u003cp>어떤 일을 당함\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">핵심\u003c/h2>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">직접 함\u003c/h3>\n\u003cblockquote>\n\u003cp>I repaired my car.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">맡겨서 받음\u003c/h3>\n\u003cblockquote>\n\u003cp>I had my car repaired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">회화형\u003c/h3>\n\u003cblockquote>\n\u003cp>I got my car repaired.\u003c/p>\n\u003c/blockquote>\n\u003cp>기본 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/get + 목적어 + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 반드시 구분:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 사람 + 동사원형\u003c/strong>\u003cbr>I had him check it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 사물 + p.p.\u003c/strong>\u003cbr>I had it checked.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I had my car \u003cstrong>repair / repaired\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I got my hair \u003cstrong>cut / to cut\u003c/strong> yesterday.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I had him \u003cstrong>check / checked\u003c/strong> the file.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I had the file \u003cstrong>check / checked\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She had her phone \u003cstrong>steal / stolen\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>I repaired my car.\u003c/code>와 \u003ccode>I had my car repaired.\u003c/code> 중 \u003cstrong>내가 직접 수리했다\u003c/strong>는 뜻은 어느 문장인지 생각해봐.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>70단계 — \u003c/strong>\u003cstrong>\u003ccode>have been / have gone\u003c/code>\u003c/strong>\u003cstrong>: 상태·경험·이동 결과 구분\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 예문","depth":2},{"id":"reading-2","label":"2. 구조","depth":2},{"id":"reading-3","label":"3. 직접 한 것과 비교","depth":2},{"id":"reading-4","label":"내가 직접 수리","depth":3},{"id":"reading-5","label":"남에게 맡겨 수리","depth":3},{"id":"reading-6","label":"4. 자주 쓰는 예","depth":2},{"id":"reading-7","label":"머리 자르기","depth":3},{"id":"reading-8","label":"치아 검사","depth":3},{"id":"reading-9","label":"집 청소","depth":3},{"id":"reading-10","label":"컴퓨터 수리","depth":3},{"id":"reading-11","label":"5. get something done","depth":2},{"id":"reading-12","label":"6. have와 get 차이","depth":2},{"id":"reading-13","label":"have","depth":3},{"id":"reading-14","label":"get","depth":3},{"id":"reading-15","label":"7. 시제는 have/get이 바뀐다","depth":2},{"id":"reading-16","label":"현재","depth":3},{"id":"reading-17","label":"과거","depth":3},{"id":"reading-18","label":"미래","depth":3},{"id":"reading-19","label":"현재완료","depth":3},{"id":"reading-20","label":"8. get도 시제 변화","depth":2},{"id":"reading-21","label":"9. 사역동사 have + 사람 + 동사원형과 비교","depth":2},{"id":"reading-22","label":"10. 비교하면 확실하다","depth":2},{"id":"reading-23","label":"11. 원치 않은 일을 당했을 때도 사용 가능","depth":2},{"id":"reading-24","label":"또 다른 예","depth":3},{"id":"reading-25","label":"핵심","depth":2},{"id":"reading-26","label":"직접 함","depth":3},{"id":"reading-27","label":"맡겨서 받음","depth":3},{"id":"reading-28","label":"회화형","depth":3},{"id":"reading-29","label":"연습","depth":2}],"origin":"notion","characters":3174,"aliases":{"structure":"reading-2","examples":"reading-1","contrast":"reading-3","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-11","topic-6":"reading-12","topic-7":"reading-15","topic-8":"reading-20","topic-9":"reading-21","topic-10":"reading-22","topic-11":"reading-23","topic-12":"reading-25"}},{"id":70,"title":"70단계 — have been / have gone 확장","html":"\u003ch1 id=\"lesson-title\" data-id=\"70\">70단계 — have been / have gone 확장\u003c/h1>\n\u003cp>50단계에서 기초 차이를 이미 봤으니, 이번에는 \u003cstrong>장소·상태·진행형에서 \u003c/strong>\u003cstrong>\u003ccode>been\u003c/code>\u003c/strong>\u003cstrong>이 어떻게 달라지는지\u003c/strong>까지 묶어서 정리한다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have been to + 장소\u003c/strong> = 가본 적 있다 / 갔다가 돌아왔다\u003cbr>\u003cstrong>have gone to + 장소\u003c/strong> = 그곳에 가 있다\u003cbr>\u003cstrong>have been + 상태/장소\u003c/strong> = 지금까지 그런 상태였다\u003cbr>\u003cstrong>have been + -ing\u003c/strong> = 계속 ~해오고 있다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>have been to + 장소\u003c/code>\u003c/h2>\n\u003cp>경험을 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I have been to Japan.\u003cbr>나는 일본에 가본 적이 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재는 보통 일본에 있다는 뜻이 아니다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">횟수와도 잘 쓴다\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve been to Japan three times.\u003cbr>일본에 세 번 가봤다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Have you ever been to Taiwan?\u003cbr>대만에 가본 적 있어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">2. \u003ccode>have gone to + 장소\u003c/code>\u003c/h2>\n\u003cp>그곳으로 떠났고 \u003cstrong>아직 돌아오지 않은 상태\u003c/strong>를 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>She has gone to the store.\u003cbr>그녀는 가게에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 여기 없고 가게에 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>Mina has \u003cstrong>been to\u003c/strong> Japan.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 일본 방문 경험이 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>Mina has \u003cstrong>gone to\u003c/strong> Japan.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 지금 일본에 가 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. \u003ccode>been\u003c/code>은 \u003ccode>be\u003c/code>의 과거분사\u003c/h2>\n\u003cp>형태:\u003c/p>\n\u003cblockquote>\n\u003cp>be → was/were → \u003cstrong>been\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서 \u003ccode>been\u003c/code>은 장소뿐 아니라 상태에도 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>been busy\u003c/strong> all day.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 하루 종일 바빴다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>been to ❌\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>been + 형용사\u003c/p>\n\u003c/blockquote>\n\u003cp>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>have been + 형용사\u003c/code>\u003c/h2>\n\u003cp>과거부터 현재까지 이어진 상태를 말할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been tired lately.\u003cbr>나 요즘 계속 피곤해.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She has been sick for three days.\u003cbr>그녀는 3일째 아프다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We&#39;ve been busy this week.\u003cbr>우리는 이번 주 계속 바쁘다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/has been + 형용사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>have been + 장소\u003c/code>\u003c/h2>\n\u003cp>장소에 계속 있었던 상태도 표현할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been at home all day.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 하루 종일 집에 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>have been \u003cstrong>at home\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>은 경험의 \u003ccode>have been to\u003c/code>와 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">비교\u003c/h2>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">경험\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve been \u003cstrong>to Seoul\u003c/strong> many times.\u003c/p>\n\u003c/blockquote>\n\u003cp>서울에 여러 번 가봤다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">위치 상태\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve been \u003cstrong>in Seoul\u003c/strong> for three days.\u003c/p>\n\u003c/blockquote>\n\u003cp>나는 3일째 서울에 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. \u003ccode>been to\u003c/code>와 \u003ccode>been in\u003c/code> 차이\u003c/h2>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">\u003ccode>been to\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>방문 경험\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ve been to Busan.\u003c/p>\n\u003c/blockquote>\n\u003cp>부산에 가본 적 있다.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">\u003ccode>been in\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>일정 기간 그 장소에 머무름\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ve been in Busan for a week.\u003c/p>\n\u003c/blockquote>\n\u003cp>부산에 일주일째 있다.\u003c/p>\n\u003cp>이 차이는 꽤 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. \u003ccode>have been + -ing\u003c/code>\u003c/h2>\n\u003cp>이전에 배운 현재완료진행형이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been \u003cstrong>working\u003c/strong> all day.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>하루 종일 계속 일하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>been = be의 과거분사\u003c/p>\n\u003c/blockquote>\n\u003cp>뒤의:\u003c/p>\n\u003cblockquote>\n\u003cp>working\u003c/p>\n\u003c/blockquote>\n\u003cp>이 진행을 만든다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/has + been + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. 세 구조 비교\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">경험\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve \u003cstrong>been to Japan\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>일본에 가본 적 있다.\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">상태\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve \u003cstrong>been busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>계속 바빴다.\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">진행\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve \u003cstrong>been working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>계속 일해오고 있다.\u003c/p>\n\u003cp>모두 \u003ccode>have been\u003c/code>이지만 뒤 구조가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">9. \u003ccode>has gone\u003c/code>의 결과 상태\u003c/h2>\n\u003cblockquote>\n\u003cp>My wife has gone to work.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>아내가 출근했고 지금 집에 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 문장은 단순히 출근했다는 과거 사건보다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그 결과 지금 여기 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 현재 상태가 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">10. \u003ccode>went\u003c/code>와 비교\u003c/h2>\n\u003cblockquote>\n\u003cp>She \u003cstrong>went\u003c/strong> to work at 8.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 8시에 출근했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>초점:\u003c/p>\n\u003cblockquote>\n\u003cp>과거 사건과 시간\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cblockquote>\n\u003cp>She \u003cstrong>has gone\u003c/strong> to work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 출근해서 지금 직장에 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>초점:\u003c/p>\n\u003cblockquote>\n\u003cp>현재 결과\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">11. \u003ccode>has been\u003c/code>이 반드시 지금까지 계속이라는 뜻은 아니다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She has been to Paris.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>과거 방문 경험\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>She has been sick for a week.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>과거부터 지금까지 계속되는 상태\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>따라서 \u003ccode>been\u003c/code> 하나의 뜻을 외우기보다 \u003cstrong>뒤에 무엇이 오는지\u003c/strong> 봐야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">핵심\u003c/h2>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">경험\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have been to + 장소\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ve been to Japan.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">가서 아직 돌아오지 않음\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have gone to + 장소\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She&#39;s gone to Japan.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">계속된 상태\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have been + 형용사/장소\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ve been busy.\u003cbr>I&#39;ve been at home all day.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">계속된 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have been + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ve been studying.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I have \u003cstrong>been to / gone to\u003c/strong> Japan three times.\u003c/p>\n\u003cp> → 방문 경험\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>My wife has \u003cstrong>been to / gone to\u003c/strong> work.\u003c/p>\n\u003cp> → 지금 직장에 가 있어서 집에 없음\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;ve \u003cstrong>been / gone\u003c/strong> busy all day.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;ve been \u003cstrong>to / in\u003c/strong> Busan for three days.\u003c/p>\n\u003cp> → 3일째 부산에 머무르고 있음\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;ve \u003cstrong>been studying / gone studying\u003c/strong> English for two hours.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>went / has gone\u003c/strong> to work at 8 this morning.\u003c/p>\n\u003cp> → 8시라는 과거 시점 강조\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>71단계 — \u003c/strong>\u003cstrong>\u003ccode>could / was able to / managed to\u003c/code>\u003c/strong>\u003cstrong>: 과거의 능력과 실제 성공 여부 구분\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. have been to + 장소","depth":2},{"id":"reading-2","label":"횟수와도 잘 쓴다","depth":3},{"id":"reading-3","label":"2. have gone to + 장소","depth":2},{"id":"reading-4","label":"비교","depth":2},{"id":"reading-5","label":"3. been은 be의 과거분사","depth":2},{"id":"reading-6","label":"4. have been + 형용사","depth":2},{"id":"reading-7","label":"5. have been + 장소","depth":2},{"id":"reading-8","label":"비교","depth":2},{"id":"reading-9","label":"경험","depth":3},{"id":"reading-10","label":"위치 상태","depth":3},{"id":"reading-11","label":"6. been to와 been in 차이","depth":2},{"id":"reading-12","label":"been to","depth":3},{"id":"reading-13","label":"been in","depth":3},{"id":"reading-14","label":"7. have been + -ing","depth":2},{"id":"reading-15","label":"8. 세 구조 비교","depth":2},{"id":"reading-16","label":"경험","depth":3},{"id":"reading-17","label":"상태","depth":3},{"id":"reading-18","label":"진행","depth":3},{"id":"reading-19","label":"9. has gone의 결과 상태","depth":2},{"id":"reading-20","label":"10. went와 비교","depth":2},{"id":"reading-21","label":"11. has been이 반드시 지금까지 계속이라는 뜻은 아니다","depth":2},{"id":"reading-22","label":"핵심","depth":2},{"id":"reading-23","label":"경험","depth":3},{"id":"reading-24","label":"가서 아직 돌아오지 않음","depth":3},{"id":"reading-25","label":"계속된 상태","depth":3},{"id":"reading-26","label":"계속된 행동","depth":3},{"id":"reading-27","label":"연습","depth":2}],"origin":"notion","characters":3198,"aliases":{"structure":"reading-15","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-3","topic-3":"reading-4","topic-4":"reading-5","topic-5":"reading-6","topic-6":"reading-7","topic-7":"reading-8","topic-8":"reading-11","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-19","topic-12":"reading-20"}},{"id":71,"title":"71단계 — could / was able to / managed to","html":"\u003ch1 id=\"lesson-title\" data-id=\"71\">71단계 — could / was able to / managed to\u003c/h1>\n\u003cp>이번에는 \u003cstrong>과거에 무엇을 할 수 있었는지\u003c/strong>, 그리고 \u003cstrong>실제로 해냈는지\u003c/strong>를 구분한다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>could = 과거의 일반적인 능력\u003c/strong>\u003cbr>\u003cstrong>was/were able to = 특정 상황에서 실제로 해냄\u003c/strong>\u003cbr>\u003cstrong>managed to = 어렵게 결국 해냄\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>could\u003c/code> — 과거의 일반적인 능력\u003c/h2>\n\u003cp>\u003ccode>can\u003c/code>의 과거형으로 가장 먼저 배운다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>can swim\u003c/strong>.\u003cbr>나는 수영할 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">과거\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>could swim\u003c/strong> when I was five.\u003cbr>나는 다섯 살 때 수영할 수 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 한 번의 사건이 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그 당시 가지고 있던 능력\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 말한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>could + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I could read.\u003cbr>She could drive.\u003cbr>They could speak English.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ could drove\u003cbr>❌ could reads\u003cbr>✅ could drive\u003cbr>✅ could read\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 일반적인 과거 능력\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>When I was young, I could run very fast.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어렸을 때 나는 아주 빨리 달릴 수 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She could speak Japanese when she was ten.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 열 살 때 일본어를 할 수 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 문장에서는 \u003ccode>could\u003c/code>가 가장 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 그런데 특정한 한 번의 성공은 다르다\u003c/h2>\n\u003cp>상황:\u003c/p>\n\u003cblockquote>\n\u003cp>어제 문이 잠겨 있었는데, 결국 열었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이때:\u003c/p>\n\u003cblockquote>\n\u003cp>I could open the door yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 하면 문맥에 따라 어색할 수 있다.\u003c/p>\n\u003cp>왜냐하면 \u003ccode>could\u003c/code>는 보통 \u003cstrong>일반적인 능력\u003c/strong>을 말하는 데 더 자연스럽기 때문이다.\u003c/p>\n\u003cp>특정한 한 번의 성공은 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I was able to open the door.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>was/were able to\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 수 있었다 / 실제로 해냈다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>was/were able to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was able to fix\u003c/strong> the computer.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 컴퓨터를 고칠 수 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>실제로 고쳤다.\u003c/p>\n\u003c/blockquote>\n\u003cp>는 뜻이 강하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">주어에 따라\u003c/h2>\n\u003cblockquote>\n\u003cp>I was able to\u003cbr>He was able to\u003cbr>She was able to\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You were able to\u003cbr>We were able to\u003cbr>They were able to\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>could\u003c/code>와 \u003ccode>was able to\u003c/code> 비교\u003c/h2>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">일반적인 능력\u003c/h3>\n\u003cblockquote>\n\u003cp>When I was younger, I \u003cstrong>could lift\u003c/strong> heavy things.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>젊었을 때는 무거운 것을 들 수 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그 당시 능력.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">특정 상황에서 성공\u003c/h3>\n\u003cblockquote>\n\u003cp>The box was very heavy, but I \u003cstrong>was able to lift\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>상자가 아주 무거웠지만 나는 들어 올릴 수 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 그 상자를 들었다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. \u003ccode>managed to\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>managed to\u003c/code>는 한 단계 더 강하다.\u003c/p>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>어렵거나 힘든 상황이었지만 결국 ~해냈다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>manage to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>과거:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>managed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>managed to finish\u003c/strong> the work on time.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 결국 제시간에 일을 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003cp>단순히 가능했다가 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>힘들었지만 어떻게든 성공했다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. 세 문장 비교\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">could\u003c/h3>\n\u003cblockquote>\n\u003cp>I could swim when I was seven.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일곱 살 때 수영할 줄 알았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 일반 능력\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">was able to\u003c/h3>\n\u003cblockquote>\n\u003cp>I was able to swim across the river.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 강을 헤엄쳐 건널 수 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 특정 상황에서 실제 성공\u003c/p>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">managed to\u003c/h3>\n\u003cblockquote>\n\u003cp>I managed to swim across the river.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 어떻게든 강을 헤엄쳐 건넜다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 힘들었지만 성공\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. \u003ccode>managed to\u003c/code>는 성공이 포함된다\u003c/h2>\n\u003cblockquote>\n\u003cp>I tried to open the door.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>문을 열려고 노력했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>성공 여부는 모른다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I managed to open the door.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>문을 \u003cstrong>결국 열었다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>try to = 시도\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>manage to = 결국 성공\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. 부정문은 조금 다르다\u003c/h2>\n\u003cp>과거에 못 했다고 말할 때는 \u003ccode>couldn&#39;t\u003c/code>이 매우 자연스럽다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>couldn&#39;t open\u003c/strong> the door.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 문을 열 수 없었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>특정한 한 번의 실패에도 \u003ccode>couldn&#39;t\u003c/code>은 잘 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">비교\u003c/h2>\n\u003cp>긍정 특정 성공:\u003c/p>\n\u003cblockquote>\n\u003cp>I was able to open the door.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정 특정 실패:\u003c/p>\n\u003cblockquote>\n\u003cp>I couldn&#39;t open the door.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 비대칭이 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">11. \u003ccode>wasn&#39;t able to\u003c/code>\u003c/h2>\n\u003cp>물론 이것도 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>wasn&#39;t able to open\u003c/strong> the door.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>문을 열 수 없었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>couldn&#39;t\u003c/code>과 비슷하지만 조금 더:\u003c/p>\n\u003cblockquote>\n\u003cp>상황상 성공하지 못했다\u003c/p>\n\u003c/blockquote>\n\u003cp>는 느낌을 줄 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">12. \u003ccode>managed not to\u003c/code>\u003c/h2>\n\u003cp>조금 다른 표현도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I managed \u003cstrong>not to laugh\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 어떻게든 웃지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>manage not to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I didn&#39;t manage to finish.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 결국 끝내지 못했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 둘은 다르다.\u003c/p>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">managed not to laugh\u003c/h3>\n\u003cblockquote>\n\u003cp>웃지 않는 데 성공\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">didn&#39;t manage to finish\u003c/h3>\n\u003cblockquote>\n\u003cp>끝내는 데 실패\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">13. 미래에서도 \u003ccode>be able to\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>could\u003c/code>만으로 모든 시제를 만들 수는 없다.\u003c/p>\n\u003cp>그래서 \u003ccode>be able to\u003c/code>가 중요하다.\u003c/p>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">미래\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will be able to\u003c/strong> help you tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일은 너를 도울 수 있을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>will + be able to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">14. 현재완료도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have been able to\u003c/strong> work from home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 재택근무를 할 수 있어 왔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 \u003ccode>be able to\u003c/code>는 시제를 다양하게 만들 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">핵심\u003c/h2>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">과거의 일반적인 능력\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>could + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I could swim when I was five.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-29\" data-reading-anchor=\"reading-29\">특정 상황에서 실제 성공\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>was/were able to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I was able to fix it.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-30\" data-reading-anchor=\"reading-30\">어렵게 결국 성공\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>managed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I managed to fix it.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">실패\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>couldn&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I couldn&#39;t fix it.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-32\" data-reading-anchor=\"reading-32\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>When I was ten, I \u003cstrong>could / managed to\u003c/strong> swim very well.\u003c/p>\n\u003cp> → 일반적인 능력\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>The door was locked, but I \u003cstrong>was able to / could usually\u003c/strong> open it.\u003c/p>\n\u003cp> → 특정 상황에서 실제로 열었음\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>The work was very difficult, but I \u003cstrong>managed to / could\u003c/strong> finish it on time.\u003c/p>\n\u003cp> → 어렵게 결국 성공\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I tried, but I \u003cstrong>couldn&#39;t / managed to\u003c/strong> lift the box.\u003c/p>\n\u003cp> → 결국 못 들었음\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>will be able to / will can\u003c/strong> help you tomorrow.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>I managed to solve the problem.\u003c/code>은 \u003cstrong>시도만 했다 / 결국 해결했다\u003c/strong> 중 어느 의미인지 생각해봐.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>72단계 — \u003c/strong>\u003cstrong>\u003ccode>must / can&#39;t / may / might\u003c/code>\u003c/strong>\u003cstrong>를 이용한 추측: \u003c/strong>\u003cstrong>\u003ccode>He must be tired\u003c/code>\u003c/strong>\u003cstrong>, \u003c/strong>\u003cstrong>\u003ccode>He can&#39;t be serious\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. could — 과거의 일반적인 능력","depth":2},{"id":"reading-2","label":"현재","depth":3},{"id":"reading-3","label":"과거","depth":3},{"id":"reading-4","label":"2. 기본 구조","depth":2},{"id":"reading-5","label":"3. 일반적인 과거 능력","depth":2},{"id":"reading-6","label":"4. 그런데 특정한 한 번의 성공은 다르다","depth":2},{"id":"reading-7","label":"5. was/were able to","depth":2},{"id":"reading-8","label":"주어에 따라","depth":2},{"id":"reading-9","label":"6. could와 was able to 비교","depth":2},{"id":"reading-10","label":"일반적인 능력","depth":3},{"id":"reading-11","label":"특정 상황에서 성공","depth":3},{"id":"reading-12","label":"7. managed to","depth":2},{"id":"reading-13","label":"8. 세 문장 비교","depth":2},{"id":"reading-14","label":"could","depth":3},{"id":"reading-15","label":"was able to","depth":3},{"id":"reading-16","label":"managed to","depth":3},{"id":"reading-17","label":"9. managed to는 성공이 포함된다","depth":2},{"id":"reading-18","label":"10. 부정문은 조금 다르다","depth":2},{"id":"reading-19","label":"비교","depth":2},{"id":"reading-20","label":"11. wasn't able to","depth":2},{"id":"reading-21","label":"12. managed not to","depth":2},{"id":"reading-22","label":"managed not to laugh","depth":3},{"id":"reading-23","label":"didn't manage to finish","depth":3},{"id":"reading-24","label":"13. 미래에서도 be able to","depth":2},{"id":"reading-25","label":"미래","depth":3},{"id":"reading-26","label":"14. 현재완료도 가능","depth":2},{"id":"reading-27","label":"핵심","depth":2},{"id":"reading-28","label":"과거의 일반적인 능력","depth":3},{"id":"reading-29","label":"특정 상황에서 실제 성공","depth":3},{"id":"reading-30","label":"어렵게 결국 성공","depth":3},{"id":"reading-31","label":"실패","depth":3},{"id":"reading-32","label":"연습","depth":2}],"origin":"notion","characters":4080,"aliases":{"structure":"reading-4","examples":"concept","contrast":"reading-9","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-17","topic-11":"reading-18","topic-12":"reading-19"}},{"id":72,"title":"72단계 — 현재에 대한 추측의 조동사","html":"\u003ch1 id=\"lesson-title\" data-id=\"72\">72단계 — 현재에 대한 추측의 조동사\u003c/h1>\n\u003cp>이번에는 \u003ccode>must\u003c/code>, \u003ccode>can&#39;t\u003c/code>, \u003ccode>may\u003c/code>, \u003ccode>might\u003c/code>가 \u003cstrong>의무나 능력\u003c/strong>이 아니라 \u003cstrong>추측\u003c/strong>에 쓰이는 경우를 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>must = 틀림없이 ~일 것이다\u003c/strong>\u003cbr>\u003cstrong>can&#39;t = ~일 리가 없다\u003c/strong>\u003cbr>\u003cstrong>may / might = ~일 수도 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cp>상태를 추측할 때:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + be + 명사/형용사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must be tired\u003c/strong>.\u003cbr>그는 틀림없이 피곤할 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cul>\n\u003cli>\u003cp>He = 주어\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>must = 추측 조동사\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>be = 동사원형\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>tired = 형용사\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ He must is tired.\u003cbr>✅ He must be tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>조동사 뒤에는 항상 \u003cstrong>동사원형\u003c/strong>이므로 \u003ccode>is\u003c/code>가 아니라 \u003ccode>be\u003c/code>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>must\u003c/code> — 강한 긍정 추측\u003c/h2>\n\u003cp>여기서 \u003ccode>must\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>반드시 해야 한다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아니다.\u003c/p>\n\u003cp>상황을 보고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>틀림없이 ~일 것이다 / 분명 ~일 것이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 추측한다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The lights are off. He \u003cstrong>must be asleep\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>불이 꺼져 있네. 그는 분명 자고 있을 거야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">또 다른 예\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;ve been working all day. You \u003cstrong>must be tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>하루 종일 일했으니 피곤하겠네.\u003c/p>\n\u003c/blockquote>\n\u003cp>직접 확인한 사실은 아니지만 근거가 있어서 강하게 추측한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. \u003ccode>must\u003c/code>의 두 가지 의미\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">의무\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>must wear\u003c/strong> a helmet.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>반드시 헬멧을 써야 한다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">추측\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>must be tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>분명 피곤하겠구나.\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 \u003ccode>must\u003c/code>지만 문맥으로 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>can&#39;t\u003c/code> — 강한 부정 추측\u003c/h2>\n\u003cp>\u003ccode>can&#39;t\u003c/code>는 여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 수 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 능력 부족이 아니라\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~일 리가 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 추측이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>can&#39;t be serious\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 진심일 리가 없어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">예\u003c/h3>\n\u003cblockquote>\n\u003cp>She can&#39;t be 70 years old.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 70살일 리가 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>말하는 사람이:\u003c/p>\n\u003cblockquote>\n\u003cp>내가 보기엔 그건 거의 불가능하다\u003c/p>\n\u003c/blockquote>\n\u003cp>고 판단한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>must not\u003c/code>과 \u003ccode>can&#39;t\u003c/code>는 다르다\u003c/h2>\n\u003cp>이게 중요하다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">mustn&#39;t\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>mustn&#39;t enter\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>들어가면 안 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>금지\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">can&#39;t\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>can&#39;t be inside\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 안에 있을 리 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>부정 추측\u003c/strong>\u003c/p>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>강한 부정 추측 = \u003cstrong>can&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라고 먼저 익히는 게 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. \u003ccode>may\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>may\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~일 수도 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>확신이 높지 않은 가능성을 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>may be busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 바쁠 수도 있어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. \u003ccode>might\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>might\u003c/code>도:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~일지도 모른다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 가능성이다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might be at home\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 집에 있을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>may\u003c/code>와 \u003ccode>might\u003c/code>는 실제 회화에서 많이 겹친다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 확신 정도\u003c/h2>\n\u003cp>대략적인 감각은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>must\u003c/strong> → 거의 확신\u003cbr>\u003cstrong>may / might\u003c/strong> → 가능성 있음\u003cbr>\u003cstrong>can&#39;t\u003c/strong> → 거의 불가능하다고 확신\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">강한 긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must be\u003c/strong> at work.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>might be\u003c/strong> at work.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">강한 부정\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>can&#39;t be\u003c/strong> at work.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">9. 일반동사를 추측할 때\u003c/h2>\n\u003cp>\u003ccode>be\u003c/code>만 가능한 것은 아니다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must know\u003c/strong> the answer.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 분명 답을 알고 있을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might like\u003c/strong> this.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 이걸 좋아할 수도 있어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He \u003cstrong>can&#39;t know\u003c/strong> everything.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 모든 것을 알 리는 없어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">10. 진행 중인 행동을 추측\u003c/h2>\n\u003cp>현재진행형과 결합할 수 있다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + be + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must be sleeping\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 분명 자고 있을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might be working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 일하고 있을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>can&#39;t be waiting\u003c/strong> for us.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그들이 우리를 기다리고 있을 리 없어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">11. 구조를 나누면\u003c/h2>\n\u003cblockquote>\n\u003cp>She might be working.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003cp>She = 주어\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>might = 조동사\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>be = 동사원형\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>working = 현재분사\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>might + be working\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>전체가:\u003c/p>\n\u003cblockquote>\n\u003cp>일하고 있을지도 모른다\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">12. 현재 사실과 비교\u003c/h2>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">사실\u003c/h3>\n\u003cblockquote>\n\u003cp>He is tired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">강한 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>He must be tired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 분명 피곤할 것이다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">약한 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>He might be tired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 피곤할지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">강한 부정\u003c/h3>\n\u003cblockquote>\n\u003cp>He can&#39;t be tired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 피곤할 리가 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">13. \u003ccode>maybe\u003c/code>와 \u003ccode>might\u003c/code>\u003c/h2>\n\u003cp>둘 다 가능성을 나타낼 수 있지만 구조가 다르다.\u003c/p>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">maybe\u003c/h3>\n\u003cp>\u003ccode>maybe\u003c/code>는 부사다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Maybe he is tired.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아마 그가 피곤할지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">might\u003c/h3>\n\u003cp>\u003ccode>might\u003c/code>는 조동사다.\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>might be tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ He maybe be tired.\u003cbr>✅ Maybe he is tired.\u003cbr>✅ He might be tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">14. \u003ccode>must\u003c/code>를 미래의 \u003ccode>will\u003c/code>과 혼동하지 않기\u003c/h2>\n\u003cblockquote>\n\u003cp>He \u003cstrong>will be\u003c/strong> at home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 집에 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>미래 예상일 수 있다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must be\u003c/strong> at home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>정황상 그는 분명 집에 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>must\u003c/code>는 \u003cstrong>현재 가진 근거를 바탕으로 한 강한 추론\u003c/strong>이라는 느낌이 강하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-30\" data-reading-anchor=\"reading-30\">핵심\u003c/h2>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">강한 긍정 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>must + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He must be tired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-32\" data-reading-anchor=\"reading-32\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>may/might + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He might be tired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-33\" data-reading-anchor=\"reading-33\">강한 부정 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>can&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He can&#39;t be tired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-34\" data-reading-anchor=\"reading-34\">진행 중인 행동 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>must/might/can&#39;t + be + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He must be sleeping.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-35\" data-reading-anchor=\"reading-35\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>You&#39;ve worked for 12 hours. You \u003cstrong>must be / must are\u003c/strong> tired.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He looks about 20. He \u003cstrong>can&#39;t be / mustn&#39;t be\u003c/strong> 70.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She isn&#39;t answering her phone. She \u003cstrong>might be / might is\u003c/strong> sleeping.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He knows everything about this project. He \u003cstrong>must know / must knows\u003c/strong> the answer.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>They may \u003cstrong>be waiting / are waiting\u003c/strong> for us.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“그가 집에 있을지도 몰라.”\u003c/p>\n\u003cp> → He \u003cstrong>might be / must be\u003c/strong> at home.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>73단계 — 과거에 대한 추측 \u003c/strong>\u003cstrong>\u003ccode>must have p.p. / can&#39;t have p.p. / might have p.p.\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. must — 강한 긍정 추측","depth":2},{"id":"reading-3","label":"또 다른 예","depth":3},{"id":"reading-4","label":"3. must의 두 가지 의미","depth":2},{"id":"reading-5","label":"의무","depth":3},{"id":"reading-6","label":"추측","depth":3},{"id":"reading-7","label":"4. can't — 강한 부정 추측","depth":2},{"id":"reading-8","label":"예","depth":3},{"id":"reading-9","label":"5. must not과 can't는 다르다","depth":2},{"id":"reading-10","label":"mustn't","depth":3},{"id":"reading-11","label":"can't","depth":3},{"id":"reading-12","label":"6. may","depth":2},{"id":"reading-13","label":"7. might","depth":2},{"id":"reading-14","label":"8. 확신 정도","depth":2},{"id":"reading-15","label":"강한 긍정","depth":3},{"id":"reading-16","label":"가능성","depth":3},{"id":"reading-17","label":"강한 부정","depth":3},{"id":"reading-18","label":"9. 일반동사를 추측할 때","depth":2},{"id":"reading-19","label":"10. 진행 중인 행동을 추측","depth":2},{"id":"reading-20","label":"11. 구조를 나누면","depth":2},{"id":"reading-21","label":"12. 현재 사실과 비교","depth":2},{"id":"reading-22","label":"사실","depth":3},{"id":"reading-23","label":"강한 추측","depth":3},{"id":"reading-24","label":"약한 추측","depth":3},{"id":"reading-25","label":"강한 부정","depth":3},{"id":"reading-26","label":"13. maybe와 might","depth":2},{"id":"reading-27","label":"maybe","depth":3},{"id":"reading-28","label":"might","depth":3},{"id":"reading-29","label":"14. must를 미래의 will과 혼동하지 않기","depth":2},{"id":"reading-30","label":"핵심","depth":2},{"id":"reading-31","label":"강한 긍정 추측","depth":3},{"id":"reading-32","label":"가능성","depth":3},{"id":"reading-33","label":"강한 부정 추측","depth":3},{"id":"reading-34","label":"진행 중인 행동 추측","depth":3},{"id":"reading-35","label":"연습","depth":2}],"origin":"notion","characters":3741,"aliases":{"structure":"reading-1","examples":"reading-3","contrast":"reading-21","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-4","topic-4":"reading-7","topic-5":"reading-9","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-18","topic-10":"reading-19","topic-11":"reading-20","topic-12":"reading-21"}},{"id":73,"title":"73단계 — 과거에 대한 추측","html":"\u003ch1 id=\"lesson-title\" data-id=\"73\">73단계 — 과거에 대한 추측\u003c/h1>\n\u003cp>이번에는 \u003cstrong>지금 과거의 일을 추측\u003c/strong>하는 표현이다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>must have + p.p.\u003c/strong> = 분명 ~했을 것이다\u003cbr>\u003cstrong>can&#39;t have + p.p.\u003c/strong> = ~했을 리가 없다\u003cbr>\u003cstrong>may/might have + p.p.\u003c/strong> = ~했을 수도 있다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 현재 추측과 비교\u003c/h2>\n\u003cp>지난 단계:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must be tired\u003c/strong>.\u003cbr>그는 분명 피곤할 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>지금 상태\u003c/strong> 추측\u003c/p>\n\u003cp>이번 단계:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must have been tired\u003c/strong>.\u003cbr>그는 분명 피곤했을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>과거 상태\u003c/strong> 추측\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>현재 추측 → \u003ccode>must + 동사원형\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>과거 추측 → \u003ccode>must have + p.p.\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>must have + p.p.\u003c/code>\u003c/h2>\n\u003cp>과거에 어떤 일이 일어났다고 \u003cstrong>강하게 추측\u003c/strong>한다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>must have forgotten\u003c/strong> the meeting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 회의를 분명 잊어버렸을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>확인한 것은 아니지만 정황상 거의 확실하다고 보는 것이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>must + have + 과거분사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>must have gone\u003cbr>must have eaten\u003cbr>must have seen\u003cbr>must have forgotten\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ must had gone\u003cbr>✅ must have gone\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>must\u003c/code> 뒤에는 동사원형이 와야 하므로 \u003ccode>have\u003c/code>가 온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. 상태를 과거로 추측\u003c/h2>\n\u003cp>현재:\u003c/p>\n\u003cblockquote>\n\u003cp>He must \u003cstrong>be tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거:\u003c/p>\n\u003cblockquote>\n\u003cp>He must \u003cstrong>have been tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜 \u003ccode>been\u003c/code>일까?\u003c/p>\n\u003cp>\u003ccode>be\u003c/code>의 과거분사가:\u003c/p>\n\u003cblockquote>\n\u003cp>be → was/were → \u003cstrong>been\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. \u003ccode>can&#39;t have + p.p.\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~했을 리가 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>can&#39;t have stolen\u003c/strong> the money.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 그 돈을 훔쳤을 리가 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>강한 \u003cstrong>부정 추측\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">예\u003c/h2>\n\u003cblockquote>\n\u003cp>She can&#39;t have finished already.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 벌써 끝냈을 리가 없어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They can&#39;t have known about it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그들이 그것을 알고 있었을 리가 없어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>mustn&#39;t have\u003c/code>가 아니다\u003c/h2>\n\u003cp>이 부분이 중요하다.\u003c/p>\n\u003cp>현재 추측에서도:\u003c/p>\n\u003cblockquote>\n\u003cp>can&#39;t = ~일 리 없다\u003c/p>\n\u003c/blockquote>\n\u003cp>였다.\u003c/p>\n\u003cp>과거 추측에서도:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>can&#39;t have p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 사용한다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ He can&#39;t have done it.\u003cbr>그가 그걸 했을 리가 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>mustn&#39;t\u003c/code>은 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>하면 안 된다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 금지 의미가 강하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>might have + p.p.\u003c/code>\u003c/h2>\n\u003cp>과거에 그 일이 일어났을 \u003cstrong>가능성\u003c/strong>을 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might have missed\u003c/strong> the bus.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 버스를 놓쳤을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cp>확실하지 않다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>may have + p.p.\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>may\u003c/code>도 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>may have left\u003c/strong> already.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 이미 떠났을 수도 있어.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>may have\u003c/code>와 \u003ccode>might have\u003c/code>는 실제 사용에서 많이 겹친다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 확신 정도 비교\u003c/h2>\n\u003cp>상황:\u003c/p>\n\u003cp>그가 어제 회의에 안 왔다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">강한 긍정 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must have forgotten\u003c/strong> the meeting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>분명 회의를 잊었을 거야.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>might have forgotten\u003c/strong> the meeting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>회의를 잊었을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">강한 부정 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>can&#39;t have forgotten\u003c/strong> the meeting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 회의를 잊었을 리는 없어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. \u003ccode>have p.p.\u003c/code>는 여기서 현재완료가 아니다\u003c/h2>\n\u003cp>겉모양은 비슷하다.\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>has left\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 떠났다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">조동사 + 완료형\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must have left\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 분명 떠났을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>have + p.p.\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 조동사 뒤에서 \u003cstrong>과거를 바라보게 만드는 완료형\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">10. 진행 중이었던 행동도 추측 가능\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>must have been + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must have been sleeping\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 분명 자고 있었을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might have been working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 일하고 있었을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. 구조 분석\u003c/h2>\n\u003cblockquote>\n\u003cp>She might have been working.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003cp>might = 가능성\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>have = 완료형\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>been = \u003ccode>be\u003c/code>의 p.p.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>working = 진행형\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>might + have been working\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>= 과거에 일하고 있었을지도 모른다\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">12. 과거 사실과 추측 비교\u003c/h2>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">사실\u003c/h3>\n\u003cblockquote>\n\u003cp>She forgot the meeting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 회의를 잊었다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">강한 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>She must have forgotten the meeting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 분명 회의를 잊었을 거야.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>She might have forgotten the meeting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 회의를 잊었을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">13. \u003ccode>could have + p.p.\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>could have\u003c/code>는 문맥에 따라 의미가 달라진다.\u003c/p>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>could have taken\u003c/strong> the wrong train.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 잘못된 기차를 탔을 수도 있어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">실제로는 하지 못한 가능성·기회\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>could have helped\u003c/strong> you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 너를 도와줄 수도 있었는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>실제로는 돕지 못했다\u003c/p>\n\u003c/blockquote>\n\u003cp>는 의미가 생길 수 있다.\u003c/p>\n\u003cp>이 표현은 뒤에서 따로 더 자세히 다룬다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">핵심\u003c/h2>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">현재 추측\u003c/h2>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must be\u003c/strong> tired.\u003cbr>분명 피곤할 거야.\u003c/p>\n\u003c/blockquote>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">과거 추측\u003c/h2>\n\u003cblockquote>\n\u003cp>He \u003cstrong>must have been\u003c/strong> tired.\u003cbr>분명 피곤했을 거야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-29\" data-reading-anchor=\"reading-29\">과거 강한 긍정 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>must have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-30\" data-reading-anchor=\"reading-30\">과거 가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>may/might have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">과거 강한 부정 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>can&#39;t have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-32\" data-reading-anchor=\"reading-32\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>She didn&#39;t come. She \u003cstrong>must have forgotten / must forgot\u003c/strong> the meeting.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He was with me all day. He \u003cstrong>can&#39;t have stolen / mustn&#39;t have stolen\u003c/strong> the car.\u003c/p>\n\u003cp> → 그가 훔쳤을 리 없다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>might have missed / might missed\u003c/strong> the bus.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He looks exhausted today. He \u003cstrong>may have slept / may slept\u003c/strong> badly last night.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>They \u003cstrong>must have been waiting / must had been waiting\u003c/strong> for us.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“그가 이미 떠났을지도 몰라.”\u003c/p>\n\u003cp> → He \u003cstrong>might have left / might left\u003c/strong> already.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>74단계 — \u003c/strong>\u003cstrong>\u003ccode>should have p.p. / shouldn&#39;t have p.p.\u003c/code>\u003c/strong>\u003cstrong>: “했어야 했다 / 하지 말았어야 했다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 현재 추측과 비교","depth":2},{"id":"reading-2","label":"2. must have + p.p.","depth":2},{"id":"reading-3","label":"구조","depth":2},{"id":"reading-4","label":"3. 상태를 과거로 추측","depth":2},{"id":"reading-5","label":"4. can't have + p.p.","depth":2},{"id":"reading-6","label":"예","depth":2},{"id":"reading-7","label":"5. mustn't have가 아니다","depth":2},{"id":"reading-8","label":"6. might have + p.p.","depth":2},{"id":"reading-9","label":"7. may have + p.p.","depth":2},{"id":"reading-10","label":"8. 확신 정도 비교","depth":2},{"id":"reading-11","label":"강한 긍정 추측","depth":3},{"id":"reading-12","label":"가능성","depth":3},{"id":"reading-13","label":"강한 부정 추측","depth":3},{"id":"reading-14","label":"9. have p.p.는 여기서 현재완료가 아니다","depth":2},{"id":"reading-15","label":"현재완료","depth":3},{"id":"reading-16","label":"조동사 + 완료형","depth":3},{"id":"reading-17","label":"10. 진행 중이었던 행동도 추측 가능","depth":2},{"id":"reading-18","label":"11. 구조 분석","depth":2},{"id":"reading-19","label":"12. 과거 사실과 추측 비교","depth":2},{"id":"reading-20","label":"사실","depth":3},{"id":"reading-21","label":"강한 추측","depth":3},{"id":"reading-22","label":"가능성","depth":3},{"id":"reading-23","label":"13. could have + p.p.","depth":2},{"id":"reading-24","label":"가능성","depth":3},{"id":"reading-25","label":"실제로는 하지 못한 가능성·기회","depth":3},{"id":"reading-26","label":"핵심","depth":2},{"id":"reading-27","label":"현재 추측","depth":2},{"id":"reading-28","label":"과거 추측","depth":2},{"id":"reading-29","label":"과거 강한 긍정 추측","depth":3},{"id":"reading-30","label":"과거 가능성","depth":3},{"id":"reading-31","label":"과거 강한 부정 추측","depth":3},{"id":"reading-32","label":"연습","depth":2}],"origin":"notion","characters":3652,"aliases":{"structure":"reading-3","examples":"reading-6","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-14","topic-12":"reading-17"}},{"id":74,"title":"74단계 — should have p.p.","html":"\u003ch1 id=\"lesson-title\" data-id=\"74\">74단계 — should have p.p.\u003c/h1>\n\u003cp>이번에는 \u003cstrong>과거에 했어야 했는데 하지 않았거나, 하지 말았어야 했는데 해버린 일\u003c/strong>을 표현한다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>should have + p.p.\u003c/strong> = ~했어야 했다\u003cbr>\u003cstrong>shouldn&#39;t have + p.p.\u003c/strong> = ~하지 말았어야 했다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>should have + p.p.\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>should have studied\u003c/strong> harder.\u003cbr>나는 더 열심히 공부했어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 상황은:\u003c/p>\n\u003cblockquote>\n\u003cp>충분히 공부하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 과거 행동에 대한 \u003cstrong>후회·아쉬움·비판\u003c/strong>이 들어간다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 현재의 \u003ccode>should\u003c/code>와 비교\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">현재/미래 조언\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>should study\u003c/strong> more.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너는 더 공부하는 게 좋다.\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 행동할 수 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">과거에 대한 아쉬움\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>should have studied\u003c/strong> more.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너는 더 공부했어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 시간이 지나갔다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>should + have + 과거분사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>should have gone\u003cbr>should have called\u003cbr>should have eaten\u003cbr>should have finished\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ should had gone\u003cbr>❌ should have went\u003cbr>✅ should have gone\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>should\u003c/code> 뒤에는 동사원형 \u003ccode>have\u003c/code>,\u003c/p>\n\u003cp>그 뒤에는 p.p.가 온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>shouldn&#39;t have + p.p.\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하지 말았어야 했다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>shouldn&#39;t have said\u003c/strong> that.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그런 말을 하지 말았어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는:\u003c/p>\n\u003cblockquote>\n\u003cp>그 말을 했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">또 다른 예\u003c/h3>\n\u003cblockquote>\n\u003cp>You shouldn&#39;t have eaten so much.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그렇게 많이 먹지 말았어야 했어.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>많이 먹었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 실제 사실은 반대\u003c/h2>\n\u003cp>이 구조는 실제 과거 행동을 자연스럽게 암시한다.\u003c/p>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">should have done\u003c/h3>\n\u003cblockquote>\n\u003cp>I should have called her.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>전화하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">shouldn&#39;t have done\u003c/h3>\n\u003cblockquote>\n\u003cp>I shouldn&#39;t have called her.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>전화했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. \u003ccode>could have\u003c/code>와 차이\u003c/h2>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">should have\u003c/h3>\n\u003cblockquote>\n\u003cp>I should have called you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너에게 전화했어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>하는 것이 옳았는데 안 했다\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">could have\u003c/h3>\n\u003cblockquote>\n\u003cp>I could have called you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너에게 전화할 수도 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>가능했지만 하지 않았다\u003c/strong>\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>should have = 의무·후회\u003cbr>could have = 가능성·기회\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. \u003ccode>would have\u003c/code>와도 다르다\u003c/h2>\n\u003cblockquote>\n\u003cp>I would have called you if I had known.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>알았더라면 전화했을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>would have\u003c/code>는 \u003cstrong>가정의 결과\u003c/strong>다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I should have called you.\u003c/p>\n\u003c/blockquote>\n\u003cp>는:\u003c/p>\n\u003cblockquote>\n\u003cp>전화했어야 했는데 안 했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. \u003ccode>should have been\u003c/code>\u003c/h2>\n\u003cp>상태에 대해서도 쓸 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>should have been more careful\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 좀 더 조심했어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>be\u003c/code>의 p.p.가 \u003ccode>been\u003c/code>이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>should + have + been\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">예\u003c/h3>\n\u003cblockquote>\n\u003cp>She should have been here by now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 지금쯤 여기 와 있어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>문맥에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>예상상 이미 도착했어야 하는데 아직 안 왔다\u003c/p>\n\u003c/blockquote>\n\u003cp>는 의미도 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. 진행 중이었어야 했던 행동\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>should have been + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You should have been studying.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너는 공부하고 있었어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>예를 들어 공부해야 할 시간에 게임하고 있었다면 쓸 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. 질문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Should I have called her?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 그녀에게 전화했어야 했나?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Should we have waited longer?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리가 더 오래 기다렸어야 했나?\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 식으로 과거 판단을 묻는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">11. 일상에서 매우 자주 쓰는 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>I should have known.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 알았어야 했는데. / 그럴 줄 알았어야 했어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I should have listened to you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네 말을 들었어야 했어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I shouldn&#39;t have done that.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그러지 말았어야 했어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You should have told me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나한테 말했어야지.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">핵심\u003c/h2>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">했어야 했다\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>should have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I should have gone.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>안 갔다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">하지 말았어야 했다\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>shouldn&#39;t have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I shouldn&#39;t have gone.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>갔다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I should have \u003cstrong>gone / went\u003c/strong> earlier.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You shouldn&#39;t have \u003cstrong>said / sayed\u003c/strong> that.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She should have \u003cstrong>called / call\u003c/strong> me.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>should have studied / should studied\u003c/strong> harder.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We shouldn&#39;t have \u003cstrong>waited / wait\u003c/strong> so long.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“나는 너에게 말했어야 했다.”\u003c/p>\n\u003cp> → I \u003cstrong>should have told / should told\u003c/strong> you.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>75단계 — \u003c/strong>\u003cstrong>\u003ccode>could have / would have / might have\u003c/code>\u003c/strong>\u003cstrong>: 과거의 가능성·가정·추측 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. should have + p.p.","depth":2},{"id":"reading-2","label":"2. 현재의 should와 비교","depth":2},{"id":"reading-3","label":"현재/미래 조언","depth":3},{"id":"reading-4","label":"과거에 대한 아쉬움","depth":3},{"id":"reading-5","label":"3. 구조","depth":2},{"id":"reading-6","label":"4. shouldn't have + p.p.","depth":2},{"id":"reading-7","label":"또 다른 예","depth":3},{"id":"reading-8","label":"5. 실제 사실은 반대","depth":2},{"id":"reading-9","label":"should have done","depth":3},{"id":"reading-10","label":"shouldn't have done","depth":3},{"id":"reading-11","label":"6. could have와 차이","depth":2},{"id":"reading-12","label":"should have","depth":3},{"id":"reading-13","label":"could have","depth":3},{"id":"reading-14","label":"7. would have와도 다르다","depth":2},{"id":"reading-15","label":"8. should have been","depth":2},{"id":"reading-16","label":"예","depth":3},{"id":"reading-17","label":"9. 진행 중이었어야 했던 행동","depth":2},{"id":"reading-18","label":"10. 질문","depth":2},{"id":"reading-19","label":"11. 일상에서 매우 자주 쓰는 표현","depth":2},{"id":"reading-20","label":"핵심","depth":2},{"id":"reading-21","label":"했어야 했다","depth":3},{"id":"reading-22","label":"하지 말았어야 했다","depth":3},{"id":"reading-23","label":"연습","depth":2}],"origin":"notion","characters":2867,"aliases":{"structure":"reading-5","examples":"reading-7","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-8","topic-6":"reading-11","topic-7":"reading-14","topic-8":"reading-15","topic-9":"reading-17","topic-10":"reading-18","topic-11":"reading-19","topic-12":"reading-20"}},{"id":75,"title":"75단계 — could have / would have / might have","html":"\u003ch1 id=\"lesson-title\" data-id=\"75\">75단계 — could have / would have / might have\u003c/h1>\n\u003cp>이번에는 과거를 돌아보며 \u003cstrong>가능성 / 가정 / 추측\u003c/strong>을 구분한다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>could have + p.p.\u003c/strong> = ~할 수 있었는데 / ~했을 수도 있다\u003cbr>\u003cstrong>would have + p.p.\u003c/strong> = ~했을 텐데\u003cbr>\u003cstrong>might have + p.p.\u003c/strong> = ~했을지도 모른다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>could have + p.p.\u003c/code> — 할 수 있었는데\u003c/h2>\n\u003cp>과거에 \u003cstrong>가능성이나 기회가 있었지만 실제로 하지 않은 것\u003c/strong>을 말할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>could have helped\u003c/strong> you.\u003cbr>내가 너를 도와줄 수도 있었는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 실제로는:\u003c/p>\n\u003cblockquote>\n\u003cp>도와주지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이 자연스럽게 따라온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>could + have + 과거분사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>could have gone\u003cbr>could have called\u003cbr>could have helped\u003cbr>could have finished\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ could had gone\u003cbr>❌ could have went\u003cbr>✅ could have gone\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>could have\u003c/code> — 과거 가능성\u003c/h2>\n\u003cp>\u003ccode>could have\u003c/code>는 또:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~했을 수도 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 추측도 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>could have taken\u003c/strong> the wrong bus.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 잘못된 버스를 탔을 수도 있어.\u003c/p>\n\u003c/blockquote>\n\u003cp>이때는 실제로 잘못된 버스를 탔는지 모른다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 두 가지 \u003ccode>could have\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">기회가 있었지만 안 함\u003c/h3>\n\u003cblockquote>\n\u003cp>I could have gone with you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나도 너와 같이 갈 수 있었는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>실제로 안 갔다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">과거 가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>He could have gone home already.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 이미 집에 갔을 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 갔는지는 모른다.\u003c/p>\n\u003cp>문맥으로 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>would have + p.p.\u003c/code> — ~했을 텐데\u003c/h2>\n\u003cp>\u003ccode>would have\u003c/code>는 보통 \u003cstrong>가정적인 결과\u003c/strong>를 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>would have helped\u003c/strong> you if I had known.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>알았더라면 너를 도왔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>몰랐다.\u003cbr>그래서 돕지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>would + have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>would have gone\u003cbr>would have bought\u003cbr>would have helped\u003cbr>would have called\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>would have\u003c/code>는 조건이 생략되기도 한다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I would have gone, but I was sick.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>갔을 텐데, 아팠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는 조건절이 숨어 있다.\u003c/p>\n\u003cp>뜻으로 풀면:\u003c/p>\n\u003cblockquote>\n\u003cp>If I hadn&#39;t been sick, I would have gone.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아프지 않았더라면 갔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>회화에서는 이런 식으로 조건을 굳이 다 말하지 않기도 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. \u003ccode>might have + p.p.\u003c/code> — ~했을지도 모른다\u003c/h2>\n\u003cp>과거의 가능성을 \u003cstrong>조심스럽게 추측\u003c/strong>한다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might have forgotten\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 잊어버렸을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He \u003cstrong>might have missed\u003c/strong> the train.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 기차를 놓쳤을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 무슨 일이 있었는지는 모른다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. \u003ccode>could have\u003c/code>와 \u003ccode>might have\u003c/code>의 추측 차이\u003c/h2>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>~했을 수도 있다\u003c/p>\n\u003c/blockquote>\n\u003cp>가 가능하다.\u003c/p>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">could have\u003c/h3>\n\u003cblockquote>\n\u003cp>He could have taken the wrong train.\u003c/p>\n\u003c/blockquote>\n\u003cp>가능한 시나리오 중 하나.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">might have\u003c/h3>\n\u003cblockquote>\n\u003cp>He might have taken the wrong train.\u003c/p>\n\u003c/blockquote>\n\u003cp>말하는 사람이 실제 가능성을 조심스럽게 추측하는 느낌.\u003c/p>\n\u003cp>둘은 실제 회화에서 많이 겹친다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. 세 표현 비교\u003c/h2>\n\u003cp>상황:\u003c/p>\n\u003cp>어제 친구가 파티에 안 왔다.\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">가능했던 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>could have come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 올 수도 있었는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 올 능력이나 기회가 있었음\u003c/p>\n\u003cp>→ 보통 실제로는 안 옴\u003c/p>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">가정적 결과\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>would have come\u003c/strong> if he had known.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 알았더라면 왔을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 조건 때문에 실제로는 안 옴\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">추측\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>might have forgotten\u003c/strong> the party.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 파티를 잊어버렸을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 왜 안 왔는지 추측\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. \u003ccode>should have\u003c/code>까지 같이 비교\u003c/h2>\n\u003cp>이전 단계까지 합치면 아주 중요하다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">표현\u003c/th>\u003cth scope=\"col\">핵심 의미\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>should have done\u003c/td>\u003ctd>했어야 했다\u003c/td>\u003c/tr>\u003ctr>\u003ctd>could have done\u003c/td>\u003ctd>할 수 있었는데 / 했을 수도 있다\u003c/td>\u003c/tr>\u003ctr>\u003ctd>would have done\u003c/td>\u003ctd>했을 텐데\u003c/td>\u003c/tr>\u003ctr>\u003ctd>might have done\u003c/td>\u003ctd>했을지도 모른다\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">같은 동사로 비교\u003c/h2>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">should have called\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>should have called\u003c/strong> her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀에게 전화했어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 후회\u003c/p>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">could have called\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>could have called\u003c/strong> her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀에게 전화할 수도 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 가능했지만 안 함\u003c/p>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">would have called\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>would have called\u003c/strong> her if I had known.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>알았더라면 전화했을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 가정적 결과\u003c/p>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">might have called\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might have called\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 나에게 전화했을지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 과거 추측\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">11. \u003ccode>couldn&#39;t have + p.p.\u003c/code>\u003c/h2>\n\u003cp>뜻은 문맥에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 수 없었을 것이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~했을 리가 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 될 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>couldn&#39;t have done\u003c/strong> it alone.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 혼자 그걸 해냈을 리가 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>강한 부정 추측으로 \u003ccode>can&#39;t have\u003c/code>와 비슷한 의미가 될 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">12. \u003ccode>wouldn&#39;t have + p.p.\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하지 않았을 텐데\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>wouldn&#39;t have bought\u003c/strong> it if I had known the price.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>가격을 알았더라면 그걸 사지 않았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">13. \u003ccode>might not have + p.p.\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하지 않았을지도 모른다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might not have seen\u003c/strong> your message.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 네 메시지를 못 봤을지도 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 단순한 과거 가능성의 부정이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">14. 핵심 감각\u003c/h2>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">후회·의무\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>should have gone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-29\" data-reading-anchor=\"reading-29\">가능했던 기회\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>could have gone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-30\" data-reading-anchor=\"reading-30\">가정적 결과\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>would have gone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">불확실한 과거 추측\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>might have gone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 \u003ccode>have gone\u003c/code>이라도 앞의 조동사가 의미를 완전히 바꾼다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-32\" data-reading-anchor=\"reading-32\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I ___ called you, but I didn&#39;t have your number.\u003c/p>\n\u003cp> → \u003cstrong>could have / might have\u003c/strong>\u003c/p>\n\u003cp> “전화할 수도 있었는데”\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If I had known, I ___ helped you.\u003c/p>\n\u003cp> → \u003cstrong>would have / might have\u003c/strong>\u003c/p>\n\u003cp> “알았더라면 도왔을 텐데.” — 가능성만이 아니라 가정의 결과를 확실하게 말함\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She isn&#39;t here. She ___ forgotten the meeting.\u003c/p>\n\u003cp> → \u003cstrong>might have / would have\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You ___ told me earlier.\u003c/p>\n\u003cp> → \u003cstrong>should have / might have\u003c/strong>\u003c/p>\n\u003cp> “더 일찍 말했어야지.”\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I ___ gone with you, but I had to work.\u003c/p>\n\u003cp> → \u003cstrong>could have / should have\u003c/strong>\u003c/p>\n\u003cp> “함께 갈 수도 있었지만 일해야 했다.” — 의무가 아니라 가능성\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If the weather had been better, we ___ gone hiking.\u003c/p>\n\u003cp> → \u003cstrong>would have / should have\u003c/strong>\u003c/p>\n\u003cp> “날씨가 더 좋았더라면 하이킹을 갔을 텐데.” — 그 조건의 가정적 결과\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>76단계 — \u003c/strong>\u003cstrong>\u003ccode>wish\u003c/code>\u003c/strong>\u003cstrong>: \u003c/strong>\u003cstrong>\u003ccode>I wish I were... / I wish I had...\u003c/code>\u003c/strong>\u003cstrong>로 현재·과거의 아쉬움 표현하기\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. could have + p.p. — 할 수 있었는데","depth":2},{"id":"reading-2","label":"2. 구조","depth":2},{"id":"reading-3","label":"3. could have — 과거 가능성","depth":2},{"id":"reading-4","label":"4. 두 가지 could have","depth":2},{"id":"reading-5","label":"기회가 있었지만 안 함","depth":3},{"id":"reading-6","label":"과거 가능성","depth":3},{"id":"reading-7","label":"5. would have + p.p. — ~했을 텐데","depth":2},{"id":"reading-8","label":"구조","depth":2},{"id":"reading-9","label":"6. would have는 조건이 생략되기도 한다","depth":2},{"id":"reading-10","label":"7. might have + p.p. — ~했을지도 모른다","depth":2},{"id":"reading-11","label":"8. could have와 might have의 추측 차이","depth":2},{"id":"reading-12","label":"could have","depth":3},{"id":"reading-13","label":"might have","depth":3},{"id":"reading-14","label":"9. 세 표현 비교","depth":2},{"id":"reading-15","label":"가능했던 행동","depth":3},{"id":"reading-16","label":"가정적 결과","depth":3},{"id":"reading-17","label":"추측","depth":3},{"id":"reading-18","label":"10. should have까지 같이 비교","depth":2},{"id":"reading-19","label":"같은 동사로 비교","depth":2},{"id":"reading-20","label":"should have called","depth":3},{"id":"reading-21","label":"could have called","depth":3},{"id":"reading-22","label":"would have called","depth":3},{"id":"reading-23","label":"might have called","depth":3},{"id":"reading-24","label":"11. couldn't have + p.p.","depth":2},{"id":"reading-25","label":"12. wouldn't have + p.p.","depth":2},{"id":"reading-26","label":"13. might not have + p.p.","depth":2},{"id":"reading-27","label":"14. 핵심 감각","depth":2},{"id":"reading-28","label":"후회·의무","depth":3},{"id":"reading-29","label":"가능했던 기회","depth":3},{"id":"reading-30","label":"가정적 결과","depth":3},{"id":"reading-31","label":"불확실한 과거 추측","depth":3},{"id":"reading-32","label":"연습","depth":2}],"origin":"notion","characters":4311,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-11","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-14","topic-11":"reading-18","topic-12":"reading-19"}},{"id":76,"title":"76단계 — wish","html":"\u003ch1 id=\"lesson-title\" data-id=\"76\">76단계 — wish\u003c/h1>\n\u003cp>이번에는 \u003cstrong>현재 사실과 다른 바람\u003c/strong>, 또는 \u003cstrong>이미 지나간 과거에 대한 아쉬움\u003c/strong>을 표현한다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + 과거형\u003c/strong> = 지금 사실과 반대되는 바람\u003cbr>\u003cstrong>wish + had + p.p.\u003c/strong> = 과거에 대한 후회\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 현재 사실과 반대 — \u003ccode>wish + 과거형\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>wish I had more time\u003c/strong>.\u003cbr>시간이 더 많으면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 사실은:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 지금 시간이 충분하지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>had\u003c/code>는 과거 시간이 아니라 \u003cstrong>현재 현실과 거리를 두는 과거형\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 가정법 과거와 연결\u003c/h2>\n\u003cp>앞에서 배운:\u003c/p>\n\u003cblockquote>\n\u003cp>If I \u003cstrong>had\u003c/strong> more time, I would read more.\u003c/p>\n\u003c/blockquote>\n\u003cp>와 같은 원리다.\u003c/p>\n\u003cp>\u003ccode>wish\u003c/code>에서도:\u003c/p>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>had\u003c/strong> more time.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>현재 현실과 다름 → 과거형\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>be동사\u003c/code>는 \u003ccode>were\u003c/code>\u003c/h2>\n\u003cp>전통적인 가정법에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I wish I were...\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>were rich\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 부자면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 부자가 아니다.\u003c/p>\n\u003c/blockquote>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>were taller\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>키가 더 크면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">회화에서는 \u003ccode>was\u003c/code>도 들린다\u003c/h2>\n\u003cblockquote>\n\u003cp>I wish I was taller.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 회화에서는 자주 쓰인다.\u003c/p>\n\u003cp>하지만 문법 학습에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I wish I were...\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 기본형으로 익히면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. 다른 주어도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>I wish \u003cstrong>she lived closer\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 더 가까이 살면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>그녀는 멀리 산다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wish \u003cstrong>he knew the answer\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 답을 알면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>그는 답을 모른다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">5. 과거에 대한 후회 — \u003ccode>wish + had + p.p.\u003c/code>\u003c/h2>\n\u003cp>이미 끝난 과거를 바꾸고 싶을 때:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + had + 과거분사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>had studied\u003c/strong> harder.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 더 열심히 공부했더라면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>충분히 공부하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">6. 현재와 과거 비교\u003c/h2>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">현재 아쉬움\u003c/h3>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>had\u003c/strong> more money.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 돈이 더 많으면 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 돈이 부족하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">과거 후회\u003c/h3>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>had had\u003c/strong> more money.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그때 돈이 더 많았으면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>당시 돈이 부족했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>had had\u003c/code>도 문법적으로 맞다.\u003c/p>\n\u003cp>첫 번째 \u003ccode>had\u003c/code> = 과거완료\u003c/p>\n\u003cp>두 번째 \u003ccode>had\u003c/code> = \u003ccode>have\u003c/code>의 p.p.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. \u003ccode>I wish I had known\u003c/code>\u003c/h2>\n\u003cp>아주 자주 쓰는 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>had known\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 그걸 알았더라면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>몰랐던 것이 아쉽다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. \u003ccode>should have\u003c/code>와 비교\u003c/h2>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">should have\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>should have called\u003c/strong> her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀에게 전화했어야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>행동에 대한 판단·후회.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">wish\u003c/h3>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>had called\u003c/strong> her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀에게 전화했더라면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거 자체가 달랐기를 바라는 느낌.\u003c/p>\n\u003cp>둘은 비슷하지만 구조가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. \u003ccode>wish + would\u003c/code>\u003c/h2>\n\u003cp>이번에는 \u003cstrong>상대방이나 상황이 앞으로 바뀌기를 바랄 때\u003c/strong> 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I wish you \u003cstrong>would be quiet\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 좀 조용히 해주면 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재 상대방이 계속 시끄러운 상황이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">또 다른 예\u003c/h2>\n\u003cblockquote>\n\u003cp>I wish it \u003cstrong>would stop raining\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>비가 좀 그치면 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재 계속 비가 오고 있고:\u003c/p>\n\u003cblockquote>\n\u003cp>이제 그쳤으면 좋겠다\u003c/p>\n\u003c/blockquote>\n\u003cp>는 불만이나 바람이 들어 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. \u003ccode>wish + would\u003c/code>는 자기 자신에게 보통 쓰지 않는다\u003c/h2>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I wish I would be taller.\u003c/p>\n\u003c/blockquote>\n\u003cp>보다는:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I wish I were taller.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 키는 내가 의지로 바꾸는 행동이 아니기 때문이다.\u003c/p>\n\u003cp>\u003ccode>would\u003c/code>는 주로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누군가의 행동이 바뀌기를 원함\u003c/strong>\u003cbr>\u003cstrong>상황이 변하기를 원함\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>에 잘 어울린다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">11. 세 가지를 한눈에\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">현재 사실과 반대\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + 과거형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wish I were taller.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재 키가 아쉽다.\u003c/p>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">과거 후회\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wish I had studied harder.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거 공부가 아쉽다.\u003c/p>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">앞으로 바뀌길 바람\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wish you would listen to me.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞으로 행동이 바뀌었으면 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">12. \u003ccode>hope\u003c/code>와 \u003ccode>wish\u003c/code> 차이\u003c/h2>\n\u003cp>이것도 중요하다.\u003c/p>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">hope\u003c/h3>\n\u003cp>실제로 일어날 가능성이 있는 바람.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>hope it doesn&#39;t rain\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일 비가 안 오면 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 내일은 오지 않았다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">wish\u003c/h3>\n\u003cp>현실과 반대되거나 어려운 바람.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>wish it weren&#39;t raining\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 비가 안 오면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 비가 온다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I hope I \u003cstrong>pass\u003c/strong> the exam.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시험에 붙었으면 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 결과가 안 나옴.\u003c/p>\n\u003cblockquote>\n\u003cp>I wish I \u003cstrong>had passed\u003c/strong> the exam.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시험에 붙었더라면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>이미 떨어졌다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">핵심\u003c/h2>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">지금 사실이 아쉬움\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + 과거형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wish I had more time.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">지나간 과거가 아쉬움\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wish I had studied harder.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">행동이나 상황이 바뀌길 바람\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>wish + would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wish you would stop.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I wish I \u003cstrong>have / had\u003c/strong> more free time.\u003c/p>\n\u003cp> → 지금 시간이 부족함\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I wish I \u003cstrong>were / am\u003c/strong> taller.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I wish I \u003cstrong>had studied / studied\u003c/strong> harder last year.\u003c/p>\n\u003cp> → 작년에 공부를 덜 한 것이 후회됨\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I wish you \u003cstrong>would stop / stopped\u003c/strong> shouting.\u003c/p>\n\u003cp> → 앞으로 좀 그만했으면 함\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>hope / wish\u003c/strong> it doesn&#39;t rain tomorrow.\u003c/p>\n\u003cp> → 아직 내일 날씨는 모름\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I wish I \u003cstrong>had known / knew\u003c/strong> about the meeting yesterday.\u003c/p>\n\u003cp> → 어제는 몰랐음\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>77단계 — \u003c/strong>\u003cstrong>\u003ccode>if only\u003c/code>\u003c/strong>\u003cstrong>: \u003c/strong>\u003cstrong>\u003ccode>wish\u003c/code>\u003c/strong>\u003cstrong>보다 강한 “~라면 얼마나 좋을까 / ~했더라면”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 현재 사실과 반대 — wish + 과거형","depth":2},{"id":"reading-2","label":"2. 가정법 과거와 연결","depth":2},{"id":"reading-3","label":"3. be동사는 were","depth":2},{"id":"reading-4","label":"회화에서는 was도 들린다","depth":2},{"id":"reading-5","label":"4. 다른 주어도 가능","depth":2},{"id":"reading-6","label":"5. 과거에 대한 후회 — wish + had + p.p.","depth":2},{"id":"reading-7","label":"6. 현재와 과거 비교","depth":2},{"id":"reading-8","label":"현재 아쉬움","depth":3},{"id":"reading-9","label":"과거 후회","depth":3},{"id":"reading-10","label":"7. I wish I had known","depth":2},{"id":"reading-11","label":"8. should have와 비교","depth":2},{"id":"reading-12","label":"should have","depth":3},{"id":"reading-13","label":"wish","depth":3},{"id":"reading-14","label":"9. wish + would","depth":2},{"id":"reading-15","label":"또 다른 예","depth":2},{"id":"reading-16","label":"10. wish + would는 자기 자신에게 보통 쓰지 않는다","depth":2},{"id":"reading-17","label":"11. 세 가지를 한눈에","depth":2},{"id":"reading-18","label":"현재 사실과 반대","depth":3},{"id":"reading-19","label":"과거 후회","depth":3},{"id":"reading-20","label":"앞으로 바뀌길 바람","depth":3},{"id":"reading-21","label":"12. hope와 wish 차이","depth":2},{"id":"reading-22","label":"hope","depth":3},{"id":"reading-23","label":"wish","depth":3},{"id":"reading-24","label":"비교","depth":2},{"id":"reading-25","label":"핵심","depth":2},{"id":"reading-26","label":"지금 사실이 아쉬움","depth":3},{"id":"reading-27","label":"지나간 과거가 아쉬움","depth":3},{"id":"reading-28","label":"행동이나 상황이 바뀌길 바람","depth":3},{"id":"reading-29","label":"연습","depth":2}],"origin":"notion","characters":3424,"aliases":{"structure":"concept","examples":"reading-15","contrast":"reading-7","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-16"}},{"id":77,"title":"77단계 — if only","html":"\u003ch1 id=\"lesson-title\" data-id=\"77\">77단계 — if only\u003c/h1>\n\u003cp>\u003ccode>if only\u003c/code>는 \u003ccode>wish\u003c/code>와 비슷하지만 \u003cstrong>아쉬움이나 바람을 더 강하게\u003c/strong> 표현한다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>if only + 과거형\u003c/strong> = 지금 ~라면 얼마나 좋을까\u003cbr>\u003cstrong>if only + had + p.p.\u003c/strong> = 그때 ~했더라면 얼마나 좋았을까\u003cbr>\u003cstrong>if only + would + 동사원형\u003c/strong> = 제발 ~해주면 좋을 텐데\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 현재 사실과 반대\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>If only I had more time.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시간이 더 많으면 정말 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 시간이 부족하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>wish\u003c/code>로 바꾸면:\u003c/p>\n\u003cblockquote>\n\u003cp>I wish I had more time.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 비슷하지만 \u003ccode>if only\u003c/code>가 보통 감정이 더 강하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>If only I were...\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>If only I \u003cstrong>were younger\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 좀 더 젊다면 얼마나 좋을까.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 지금 더 젊지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cp>가정법과 마찬가지로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>were\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 기본형으로 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 과거에 대한 후회\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>if only + had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If only I \u003cstrong>had studied\u003c/strong> harder.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 더 열심히 공부했더라면 얼마나 좋았을까.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>충분히 공부하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>wish\u003c/code>와 비교\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">wish\u003c/h3>\n\u003cblockquote>\n\u003cp>I wish I had called her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀에게 전화했더라면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">if only\u003c/h3>\n\u003cblockquote>\n\u003cp>If only I had called her!\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그때 그녀한테 전화만 했더라면!\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>if only\u003c/code> 쪽이 \u003cstrong>후회나 감정이 더 강하게\u003c/strong> 느껴진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 문장 하나만으로도 완전한 표현\u003c/h2>\n\u003cp>보통 \u003ccode>if\u003c/code>를 보면 뒤에 결과절이 필요하다고 생각할 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I have time, I&#39;ll go.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 \u003ccode>if only\u003c/code>는 독립적으로 끝날 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>If only I knew!\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 알기만 한다면!\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If only she were here!\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 여기 있기만 한다면!\u003c/p>\n\u003c/blockquote>\n\u003cp>뒤에 \u003ccode>I would...\u003c/code> 같은 결과절이 없어도 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>if only + would\u003c/code>\u003c/h2>\n\u003cp>상대방이나 상황이 \u003cstrong>좀 바뀌었으면 하는 강한 바람\u003c/strong>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>If only you \u003cstrong>would listen\u003c/strong> to me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>제발 내 말 좀 들어주면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If only it \u003cstrong>would stop raining\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>비가 제발 좀 그치면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>wish + would\u003c/code>와 매우 비슷하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 세 가지 시점\u003c/h2>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">현재가 아쉬움\u003c/h2>\n\u003cblockquote>\n\u003cp>If only I \u003cstrong>had\u003c/strong> more money.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 돈이 더 있다면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">과거가 아쉬움\u003c/h2>\n\u003cblockquote>\n\u003cp>If only I \u003cstrong>had had\u003c/strong> more money.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그때 돈이 더 있었더라면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">앞으로 상황이 바뀌길 바람\u003c/h2>\n\u003cblockquote>\n\u003cp>If only he \u003cstrong>would call\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 제발 전화해주면 좋을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. \u003ccode>only if\u003c/code>와 혼동하면 안 된다\u003c/h2>\n\u003cp>이 둘은 완전히 다르다.\u003c/p>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">if only\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>~라면 얼마나 좋을까\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If only I had more time.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">only if\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>오직 ~하는 경우에만\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You can go \u003cstrong>only if you finish your work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일을 끝내야만 갈 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>단어 순서만 바뀌었는데 의미가 완전히 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">핵심\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">현재 아쉬움\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If only + 과거형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If only I were rich.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">과거 후회\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If only + had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If only I had known.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">변화 바람\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>If only + would + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If only you would stop.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>wish\u003c/code>보다 보통 \u003cstrong>감정이 더 강하다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>If only I \u003cstrong>have / had\u003c/strong> more time.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If only she \u003cstrong>were / is\u003c/strong> here.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If only I \u003cstrong>had known / knew\u003c/strong> about it yesterday.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>If only you \u003cstrong>would listen / will listen\u003c/strong> to me.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>If only / Only if\u003c/strong> I were younger!\u003c/p>\n\u003cp> → 내가 좀 더 젊다면 얼마나 좋을까.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You can leave \u003cstrong>if only / only if\u003c/strong> you finish the work.\u003c/p>\n\u003cp> → 일을 끝낸 경우에만 떠날 수 있다.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>78단계 — \u003c/strong>\u003cstrong>\u003ccode>would rather\u003c/code>\u003c/strong>\u003cstrong>: “차라리 ~하겠다 / ~했으면 좋겠다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 현재 사실과 반대","depth":2},{"id":"reading-2","label":"2. If only I were...","depth":2},{"id":"reading-3","label":"3. 과거에 대한 후회","depth":2},{"id":"reading-4","label":"4. wish와 비교","depth":2},{"id":"reading-5","label":"wish","depth":3},{"id":"reading-6","label":"if only","depth":3},{"id":"reading-7","label":"5. 문장 하나만으로도 완전한 표현","depth":2},{"id":"reading-8","label":"6. if only + would","depth":2},{"id":"reading-9","label":"7. 세 가지 시점","depth":2},{"id":"reading-10","label":"현재가 아쉬움","depth":2},{"id":"reading-11","label":"과거가 아쉬움","depth":2},{"id":"reading-12","label":"앞으로 상황이 바뀌길 바람","depth":2},{"id":"reading-13","label":"8. only if와 혼동하면 안 된다","depth":2},{"id":"reading-14","label":"if only","depth":3},{"id":"reading-15","label":"only if","depth":3},{"id":"reading-16","label":"핵심","depth":2},{"id":"reading-17","label":"현재 아쉬움","depth":3},{"id":"reading-18","label":"과거 후회","depth":3},{"id":"reading-19","label":"변화 바람","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"notion","characters":2360,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-16"}},{"id":78,"title":"78단계 — would rather","html":"\u003ch1 id=\"lesson-title\" data-id=\"78\">78단계 — would rather\u003c/h1>\n\u003cp>\u003ccode>would rather\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>차라리 ~하겠다 / ~하는 편이 낫다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 선호를 나타낸다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>would rather stay\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차라리 집에 있겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>축약하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I&#39;d rather stay home.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I&#39;d\u003c/code> = \u003ccode>I would\u003c/code>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 왜 \u003ccode>to\u003c/code>가 없나?\u003c/h2>\n\u003cp>\u003ccode>would rather\u003c/code> 뒤에는 \u003cstrong>동사원형\u003c/strong>이 바로 온다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I&#39;d rather \u003cstrong>go\u003c/strong> home.\u003cbr>❌ I&#39;d rather \u003cstrong>to go\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>had better\u003c/code>와 비슷하게 통째로 익히면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 두 가지 중 하나를 선택할 때\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;d rather drink coffee.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차라리 커피를 마시겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>비교 대상을 붙이면:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d rather drink coffee \u003cstrong>than tea\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차보다 커피를 마시겠다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">더 정확한 구조\u003c/h2>\n\u003cp>행동끼리 비교하면:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>stay home than go out\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 밖에 나가느니 차라리 집에 있겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather A than B\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. \u003ccode>prefer\u003c/code>와 비교\u003c/h2>\n\u003cp>둘 다 선호를 나타낸다.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">would rather\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather stay home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>차라리 집에 있을래.\u003c/p>\n\u003c/blockquote>\n\u003cp>특정 상황에서의 선택에 아주 자연스럽다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">prefer\u003c/h3>\n\u003cblockquote>\n\u003cp>I prefer staying home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 집에 있는 것을 더 선호한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>일반적인 취향에도 잘 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 부정형\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather not + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>not go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차라리 안 갈래.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She&#39;d rather \u003cstrong>not talk\u003c/strong> about it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 그 얘기를 하지 않는 편을 택하겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>위치는:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ rather not go\u003cbr>❌ rather don&#39;t go\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 질문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Would you rather stay home or go out?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>집에 있을래, 밖에 나갈래?\u003c/p>\n\u003c/blockquote>\n\u003cp>이 구조는 실제 회화에서 아주 자주 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>Would you rather have coffee or tea?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>커피 마실래, 차 마실래?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. 다른 사람이 ~했으면 좋겠다\u003c/h2>\n\u003cp>여기서 구조가 크게 달라진다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">내가 행동할 때\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>stay\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 집에 있는 편이 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">다른 사람이 행동하기를 원할 때\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>you stayed\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 네가 집에 있었으면 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜 \u003ccode>stayed\u003c/code>일까?\u003c/p>\n\u003cp>\u003ccode>would rather + 다른 주어\u003c/code> 뒤에서는 \u003cstrong>과거형\u003c/strong>을 써서 현재/미래에 대한 바람을 나타낸다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. \u003ccode>would rather + 사람 + 과거형\u003c/code>\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather + 주어 + 과거형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>you came\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 네가 내일 오는 편이 좋겠어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>he didn&#39;t know\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그가 모르는 편이 좋겠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 과거형이지만 \u003cstrong>과거 이야기인 것은 아니다.\u003c/strong>\u003c/p>\n\u003cp>가정법과 비슷하게:\u003c/p>\n\u003cblockquote>\n\u003cp>현실과 거리를 두는 과거형\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. 비교\u003c/h2>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">내가 한다\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>go\u003c/strong> alone.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">네가 한다\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>you went\u003c/strong> alone.\u003c/p>\n\u003c/blockquote>\n\u003cp>첫 번째:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>would rather + 동사원형\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>would rather + 사람 + 과거형\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 차이는 꼭 기억해야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">10. 과거에 대한 아쉬움\u003c/h2>\n\u003cp>이미 지나간 일에 대해:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather + 사람 + had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 사용할 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d rather you \u003cstrong>had told\u003c/strong> me earlier.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 나에게 더 일찍 말했으면 좋았을 텐데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로는:\u003c/p>\n\u003cblockquote>\n\u003cp>더 일찍 말하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. 세 구조 정리\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">내가 지금/앞으로 할 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>stay\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">다른 사람이 지금/앞으로 하길 바람\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>you stayed\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">다른 사람이 과거에 다르게 했길 바람\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>you had stayed\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">12. \u003ccode>rather than\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>rather than\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하기보다는 / ~대신에\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d walk \u003cstrong>rather than take a taxi\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>택시를 타느니 걷겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>He chose to stay home \u003cstrong>rather than go out\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 밖에 나가는 대신 집에 있기로 했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">핵심\u003c/h2>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">내가 선택\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;d rather go.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather not + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;d rather not go.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">다른 사람이 하길 원함\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather + 사람 + 과거형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;d rather you stayed.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">과거가 달랐길 원함\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>would rather + 사람 + had + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;d rather you had told me.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I&#39;d rather \u003cstrong>stay / to stay\u003c/strong> home.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;d rather \u003cstrong>not go / don&#39;t go\u003c/strong> tonight.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;d rather \u003cstrong>drink coffee than tea / drink coffee to tea\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;d rather \u003cstrong>you stayed / you stay\u003c/strong> home tonight.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;d rather you \u003cstrong>had told / told\u003c/strong> me yesterday.\u003c/p>\n\u003cp> → 어제 더 일찍 말했으면 좋았을 텐데.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Would you rather \u003cstrong>eat / to eat\u003c/strong> at home or go out?\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>79단계 — \u003c/strong>\u003cstrong>\u003ccode>had better\u003c/code>\u003c/strong>\u003cstrong>: “~하는 게 좋겠다”와 \u003c/strong>\u003cstrong>\u003ccode>should\u003c/code>\u003c/strong>\u003cstrong>의 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 왜 to가 없나?","depth":2},{"id":"reading-3","label":"3. 두 가지 중 하나를 선택할 때","depth":2},{"id":"reading-4","label":"더 정확한 구조","depth":2},{"id":"reading-5","label":"4. prefer와 비교","depth":2},{"id":"reading-6","label":"would rather","depth":3},{"id":"reading-7","label":"prefer","depth":3},{"id":"reading-8","label":"5. 부정형","depth":2},{"id":"reading-9","label":"6. 질문","depth":2},{"id":"reading-10","label":"7. 다른 사람이 ~했으면 좋겠다","depth":2},{"id":"reading-11","label":"내가 행동할 때","depth":3},{"id":"reading-12","label":"다른 사람이 행동하기를 원할 때","depth":3},{"id":"reading-13","label":"8. would rather + 사람 + 과거형","depth":2},{"id":"reading-14","label":"9. 비교","depth":2},{"id":"reading-15","label":"내가 한다","depth":3},{"id":"reading-16","label":"네가 한다","depth":3},{"id":"reading-17","label":"10. 과거에 대한 아쉬움","depth":2},{"id":"reading-18","label":"11. 세 구조 정리","depth":2},{"id":"reading-19","label":"내가 지금/앞으로 할 행동","depth":3},{"id":"reading-20","label":"다른 사람이 지금/앞으로 하길 바람","depth":3},{"id":"reading-21","label":"다른 사람이 과거에 다르게 했길 바람","depth":3},{"id":"reading-22","label":"12. rather than","depth":2},{"id":"reading-23","label":"핵심","depth":2},{"id":"reading-24","label":"내가 선택","depth":3},{"id":"reading-25","label":"부정","depth":3},{"id":"reading-26","label":"다른 사람이 하길 원함","depth":3},{"id":"reading-27","label":"과거가 달랐길 원함","depth":3},{"id":"reading-28","label":"연습","depth":2}],"origin":"notion","characters":3168,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-17","topic-12":"reading-18"}},{"id":79,"title":"79단계 — had better","html":"\u003ch1 id=\"lesson-title\" data-id=\"79\">79단계 — had better\u003c/h1>\n\u003cp>\u003ccode>had better\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하는 게 좋겠다 / ~해야겠다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cp>형태에 \u003ccode>had\u003c/code>가 있지만 \u003cstrong>과거 의미가 아니다.\u003c/strong>\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had better + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>You \u003cstrong>had better go\u003c/strong> now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너 지금 가는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>회화에서는 거의 항상 축약한다.\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;d better go now.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>You&#39;d = You had\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ You had better \u003cstrong>to go\u003c/strong>\u003cbr>❌ You had better \u003cstrong>went\u003c/strong>\u003cbr>✅ You had better \u003cstrong>go\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>should\u003c/code>와 차이\u003c/h2>\n\u003cp>둘 다 한국어로:\u003c/p>\n\u003cblockquote>\n\u003cp>~하는 게 좋다\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 번역될 수 있다.\u003c/p>\n\u003cp>하지만 강도가 다르다.\u003c/p>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">\u003ccode>should\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>should leave\u003c/strong> now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 출발하는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003cp>일반적인 \u003cstrong>조언\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">\u003ccode>had better\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;d \u003cstrong>better leave\u003c/strong> now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 출발하는 게 좋겠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기에는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>안 그러면 안 좋은 결과가 생길 수 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 느낌이 있다.\u003c/p>\n\u003cp>예를 들어 비행기를 타야 한다면:\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;d better leave now. The traffic is getting worse.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 출발하는 게 좋겠어. 길이 점점 막히고 있어.\u003c/p>\n\u003c/blockquote>\n\u003cp>숨은 의미:\u003c/p>\n\u003cblockquote>\n\u003cp>안 가면 늦을 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. \u003ccode>had better\u003c/code>의 핵심 감각\u003c/h2>\n\u003cp>단순한 추천보다는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금 이 상황에서는 그렇게 하는 것이 현명하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003cp>그리고 종종 \u003cstrong>경고\u003c/strong>가 포함된다.\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;d better take an umbrella.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우산 가져가는 게 좋겠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>상황:\u003c/p>\n\u003cblockquote>\n\u003cp>비가 올 것 같다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cblockquote>\n\u003cp>You&#39;d better study for the exam.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시험공부하는 게 좋을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>상황에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>안 하면 시험에 떨어질 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뉘앙스가 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 부정형\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had better not + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;d better \u003cstrong>not be late\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>늦지 않는 게 좋을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We&#39;d better \u003cstrong>not tell him\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그에게는 말하지 않는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ had better \u003cstrong>not go\u003c/strong>\u003cbr>❌ had not better go\u003cbr>❌ had better don&#39;t go\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>shouldn&#39;t\u003c/code>과 비교\u003c/h2>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">일반적인 조언\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>shouldn&#39;t eat\u003c/strong> too much.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너무 많이 먹지 않는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">좀 더 강한 경고\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;d \u003cstrong>better not eat\u003c/strong> that.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그거 안 먹는 게 좋을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째는 상황에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>상했을 수도 있다 / 먹으면 문제가 생길 수 있다\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 경고가 느껴진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>had\u003c/code>라고 해서 과거가 아니다\u003c/h2>\n\u003cp>이 부분이 특히 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>had better go now\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 가는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>had\u003c/code>가 있지만:\u003c/p>\n\u003cblockquote>\n\u003cp>“과거에 가는 게 좋았다” ❌\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아니다.\u003c/p>\n\u003cp>\u003ccode>had better\u003c/code> 전체가 하나의 \u003cstrong>고정된 조동사적 표현\u003c/strong>이다.\u003c/p>\n\u003cp>그래서 통째로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had better + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>으로 익힌다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. 시제를 바꾸지 않는다\u003c/h2>\n\u003cp>일반적인 \u003ccode>have\u003c/code>처럼:\u003c/p>\n\u003cblockquote>\n\u003cp>have better\u003cbr>will have better\u003c/p>\n\u003c/blockquote>\n\u003cp>로 바꾸는 표현이 아니다.\u003c/p>\n\u003cp>현재나 가까운 미래에 대한 조언·경고에 주로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had better\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>형태 그대로 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;d better call her tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일 그녀에게 전화하는 게 좋겠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>tomorrow\u003c/code>인데도 \u003ccode>had better\u003c/code>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>I&#39;d better\u003c/code>\u003c/h2>\n\u003cp>매우 자주 쓰인다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I&#39;d better go.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나 이제 가봐야겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>I&#39;d\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I had\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>\u003ccode>I would better\u003c/code>가 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">실제 회화 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;d better get going.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나 이제 슬슬 가봐야겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>get going\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>출발하다 / 움직이기 시작하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 자주 쓰는 표현이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. \u003ccode>We&#39;d better...\u003c/code>\u003c/h2>\n\u003cp>같이 해야 할 일을 판단할 때도 많이 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>We&#39;d better hurry.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리 서두르는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We&#39;d better book the hotel now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리 지금 호텔을 예약하는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. 질문형은 가능하지만 덜 흔하다\u003c/h2>\n\u003cp>문법적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>Had we better leave now?\u003c/p>\n\u003c/blockquote>\n\u003cp>가능하다.\u003c/p>\n\u003cp>하지만 현대 회화에서는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Should we leave now?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리 지금 가는 게 좋을까?\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>should\u003c/code>를 쓰는 것이 훨씬 자연스럽다.\u003c/p>\n\u003cp>\u003ccode>had better\u003c/code>는 주로 \u003cstrong>평서문과 부정문\u003c/strong>에서 익히면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">11. \u003ccode>would rather\u003c/code>와 비교\u003c/h2>\n\u003cp>지난 단계와 형태가 비슷하다.\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">would rather\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather \u003cstrong>stay\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차라리 집에 있겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>선호\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">had better\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d better \u003cstrong>stay\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 집에 있는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>상황상 그렇게 해야 함\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;d rather not go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차라리 안 가고 싶다.\u003c/p>\n\u003c/blockquote>\n\u003cp>개인적인 선택.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;d better not go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 안 가는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>가면 문제가 생길 수 있다는 판단.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">12. \u003ccode>should / had better / must\u003c/code>\u003c/h2>\n\u003cp>강도를 비교하면:\u003c/p>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">should\u003c/h3>\n\u003cblockquote>\n\u003cp>You should call him.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>전화하는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>조언\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">had better\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;d better call him.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>전화하는 게 좋을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>조언 + 안 하면 문제가 생길 수 있음\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">must\u003c/h3>\n\u003cblockquote>\n\u003cp>You must call him.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>반드시 전화해야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>강한 의무\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">핵심\u003c/h2>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>had better + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You&#39;d better go.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>had better not + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You&#39;d better not go.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>had better\u003c/code>의 \u003ccode>had\u003c/code>는 \u003cstrong>과거 의미가 아니다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>should\u003c/code>보다 보통 더 강하고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>“안 그러면 문제가 생길 수 있다”\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 느낌이 들어간다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>You&#39;d better \u003cstrong>go / to go\u003c/strong> now.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We&#39;d better \u003cstrong>not wait / don&#39;t wait\u003c/strong> any longer.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>had better / would better\u003c/strong> call her.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You ___ take an umbrella. It looks like it&#39;s going to rain.\u003c/p>\n\u003cp> → \u003cstrong>had better / would rather\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;d ___ stay home than go out.\u003c/p>\n\u003cp> → \u003cstrong>rather / better\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>You should leave now.\u003c/code>와 \u003ccode>You&#39;d better leave now.\u003c/code> 중 \u003cstrong>안 떠나면 문제가 생길 수 있다는 경고가 더 강한 표현\u003c/strong>은 무엇인지 생각해봐.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>80단계 — \u003c/strong>\u003cstrong>\u003ccode>be supposed to\u003c/code>\u003c/strong>\u003cstrong>: “~하기로 되어 있다 / ~해야 한다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. should와 차이","depth":2},{"id":"reading-3","label":"should","depth":3},{"id":"reading-4","label":"had better","depth":3},{"id":"reading-5","label":"3. had better의 핵심 감각","depth":2},{"id":"reading-6","label":"4. 부정형","depth":2},{"id":"reading-7","label":"5. shouldn't과 비교","depth":2},{"id":"reading-8","label":"일반적인 조언","depth":3},{"id":"reading-9","label":"좀 더 강한 경고","depth":3},{"id":"reading-10","label":"6. had라고 해서 과거가 아니다","depth":2},{"id":"reading-11","label":"7. 시제를 바꾸지 않는다","depth":2},{"id":"reading-12","label":"8. I'd better","depth":2},{"id":"reading-13","label":"실제 회화 표현","depth":2},{"id":"reading-14","label":"9. We'd better...","depth":2},{"id":"reading-15","label":"10. 질문형은 가능하지만 덜 흔하다","depth":2},{"id":"reading-16","label":"11. would rather와 비교","depth":2},{"id":"reading-17","label":"would rather","depth":3},{"id":"reading-18","label":"had better","depth":3},{"id":"reading-19","label":"비교","depth":2},{"id":"reading-20","label":"12. should / had better / must","depth":2},{"id":"reading-21","label":"should","depth":3},{"id":"reading-22","label":"had better","depth":3},{"id":"reading-23","label":"must","depth":3},{"id":"reading-24","label":"핵심","depth":2},{"id":"reading-25","label":"긍정","depth":3},{"id":"reading-26","label":"부정","depth":3},{"id":"reading-27","label":"연습","depth":2}],"origin":"notion","characters":3720,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-16"}},{"id":80,"title":"80단계 — be supposed to","html":"\u003ch1 id=\"lesson-title\" data-id=\"80\">80단계 — be supposed to\u003c/h1>\n\u003cp>\u003ccode>be supposed to\u003c/code>는 \u003cstrong>규칙·예정·기대된 행동\u003c/strong>을 나타낸다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be supposed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 의미\u003c/h2>\n\u003cp>가장 기본적인 뜻은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하기로 되어 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am supposed to meet\u003c/strong> him at 3.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 3시에 그를 만나기로 되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 어떤 \u003cstrong>약속이나 일정\u003c/strong>이 잡혀 있다는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 주어에 따라 be동사가 바뀐다\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am supposed to\u003c/strong> go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He \u003cstrong>is supposed to\u003c/strong> go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>are supposed to\u003c/strong> go.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>am/is/are + supposed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. 규칙이나 의무\u003c/h2>\n\u003cp>\u003ccode>be supposed to\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~해야 한다 / ~하는 것이 규칙이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻도 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>are supposed to wear\u003c/strong> a helmet here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기서는 헬멧을 써야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>느낌은:\u003c/p>\n\u003cblockquote>\n\u003cp>“원래 규칙상 그렇게 하게 되어 있다.”\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. \u003ccode>must\u003c/code>와 차이\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">must\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>must wear\u003c/strong> a helmet.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>반드시 헬멧을 써야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>강한 의무.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">be supposed to\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>are supposed to wear\u003c/strong> a helmet.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>원래 헬멧을 쓰게 되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>규칙이나 기대를 설명하는 느낌이 더 강하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 예정된 일\u003c/h2>\n\u003cblockquote>\n\u003cp>The meeting \u003cstrong>is supposed to start\u003c/strong> at 9.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>회의는 9시에 시작하기로 되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 중요한 점:\u003c/p>\n\u003cblockquote>\n\u003cp>실제로 9시에 시작한다고 100% 보장하는 표현은 아니다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>예정상 그렇다\u003c/strong>는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 사람에게 기대되는 행동\u003c/h2>\n\u003cblockquote>\n\u003cp>You&#39;re \u003cstrong>supposed to help\u003c/strong> your team.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너는 팀을 도와야 해.\u003c/p>\n\u003c/blockquote>\n\u003cp>단순한 명령이라기보다:\u003c/p>\n\u003cblockquote>\n\u003cp>네 역할상 그렇게 하는 것이 맞다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. 부정형\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>be not supposed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하면 안 된다 / ~하지 않기로 되어 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;re \u003cstrong>not supposed to park\u003c/strong> here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기 주차하면 안 돼.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We&#39;re \u003cstrong>not supposed to use\u003c/strong> this door.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리는 이 문을 사용하면 안 된다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. \u003ccode>mustn&#39;t\u003c/code>와 차이\u003c/h2>\n\u003cp>둘 다 금지를 표현할 수 있다.\u003c/p>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">mustn&#39;t\u003c/h3>\n\u003cblockquote>\n\u003cp>You mustn&#39;t enter.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>절대 들어가면 안 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>더 강한 금지.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">not supposed to\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;re not supposed to enter.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>원래 들어가면 안 되는 곳이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>규칙 위반이라는 느낌.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. 과거형\u003c/h2>\n\u003cp>과거에는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>was/were supposed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하기로 되어 있었다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was supposed to call\u003c/strong> her yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 어제 그녀에게 전화하기로 되어 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 표현은 문맥상 자주:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그런데 실제로는 못 했다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미를 암시한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. \u003ccode>was supposed to\u003c/code>의 핵심 뉘앙스\u003c/h2>\n\u003cblockquote>\n\u003cp>I was supposed to meet him at 2.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>2시에 만나기로 되어 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 자주 뒤에:\u003c/p>\n\u003cblockquote>\n\u003cp>but I forgot.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그런데 깜빡했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>가 자연스럽게 이어진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">11. 현재와 과거 비교\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m supposed to work today.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>오늘 일하기로 되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">과거\u003c/h3>\n\u003cblockquote>\n\u003cp>I was supposed to work yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어제 일하기로 되어 있었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">12. 의문문\u003c/h2>\n\u003cp>be동사를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Am I supposed to wait here?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>제가 여기서 기다리면 되나요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Are we supposed to pay now?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리 지금 계산해야 하나요?\u003c/p>\n\u003c/blockquote>\n\u003cp>이 구조는 실제 회화에서 매우 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">13. \u003ccode>What am I supposed to do?\u003c/code>\u003c/h2>\n\u003cp>아주 중요한 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>What am I supposed to do?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>직역:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 무엇을 해야 하기로 되어 있지?\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 의미:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>나보고 어떻게 하라는 거야? / 내가 뭘 해야 해?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>상황에 따라 답답함이나 당황스러움도 들어갈 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">14. \u003ccode>supposed to be\u003c/code>\u003c/h2>\n\u003cp>상태나 정체를 말할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>This \u003cstrong>is supposed to be\u003c/strong> easy.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이건 원래 쉬워야 하는데.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He \u003cstrong>is supposed to be\u003c/strong> an expert.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 전문가라고 알려져 있다 / 전문가인 것으로 되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">15. 예상과 현실이 다를 때\u003c/h2>\n\u003cp>이 표현은 \u003cstrong>예상과 실제가 다를 때\u003c/strong> 특히 자주 나온다.\u003c/p>\n\u003cblockquote>\n\u003cp>It&#39;s supposed to be sunny today.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>오늘은 날씨가 맑기로 되어 있는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>그런데 실제로 비가 오고 있을 수도 있다.\u003c/p>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>This is supposed to work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이건 원래 작동해야 하는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>그런데 지금 작동하지 않는 상황에서 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">16. \u003ccode>should\u003c/code>와 비교\u003c/h2>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">should\u003c/h3>\n\u003cblockquote>\n\u003cp>You should call him.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그에게 전화하는 게 좋다.\u003c/p>\n\u003c/blockquote>\n\u003cp>조언.\u003c/p>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">be supposed to\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;re supposed to call him.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 그에게 전화하기로 되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 역할·약속·규칙이 존재한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">핵심\u003c/h2>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">예정 / 규칙 / 기대\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>be supposed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m supposed to meet him.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">금지\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>be not supposed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You&#39;re not supposed to smoke here.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-29\" data-reading-anchor=\"reading-29\">과거 예정\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>was/were supposed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I was supposed to call her.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-30\" data-reading-anchor=\"reading-30\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I am supposed to \u003cstrong>meet / meeting\u003c/strong> him at 3.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You \u003cstrong>are supposed to / supposed\u003c/strong> wear a helmet here.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You&#39;re \u003cstrong>not supposed to / don&#39;t supposed to\u003c/strong> park here.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>was supposed to / am supposed to\u003c/strong> call her yesterday.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Am I supposed to / Do I supposed to\u003c/strong> wait here?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“원래 이건 작동해야 하는데.”\u003c/p>\n\u003cp> → This \u003cstrong>is supposed to work / supposed to works\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>81단계 — \u003c/strong>\u003cstrong>\u003ccode>be allowed to / let\u003c/code>\u003c/strong>\u003cstrong>: “~해도 된다 / 허락받다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 의미","depth":2},{"id":"reading-2","label":"2. 주어에 따라 be동사가 바뀐다","depth":2},{"id":"reading-3","label":"현재","depth":3},{"id":"reading-4","label":"3. 규칙이나 의무","depth":2},{"id":"reading-5","label":"4. must와 차이","depth":2},{"id":"reading-6","label":"must","depth":3},{"id":"reading-7","label":"be supposed to","depth":3},{"id":"reading-8","label":"5. 예정된 일","depth":2},{"id":"reading-9","label":"6. 사람에게 기대되는 행동","depth":2},{"id":"reading-10","label":"7. 부정형","depth":2},{"id":"reading-11","label":"8. mustn't와 차이","depth":2},{"id":"reading-12","label":"mustn't","depth":3},{"id":"reading-13","label":"not supposed to","depth":3},{"id":"reading-14","label":"9. 과거형","depth":2},{"id":"reading-15","label":"10. was supposed to의 핵심 뉘앙스","depth":2},{"id":"reading-16","label":"11. 현재와 과거 비교","depth":2},{"id":"reading-17","label":"현재","depth":3},{"id":"reading-18","label":"과거","depth":3},{"id":"reading-19","label":"12. 의문문","depth":2},{"id":"reading-20","label":"13. What am I supposed to do?","depth":2},{"id":"reading-21","label":"14. supposed to be","depth":2},{"id":"reading-22","label":"15. 예상과 현실이 다를 때","depth":2},{"id":"reading-23","label":"16. should와 비교","depth":2},{"id":"reading-24","label":"should","depth":3},{"id":"reading-25","label":"be supposed to","depth":3},{"id":"reading-26","label":"핵심","depth":2},{"id":"reading-27","label":"예정 / 규칙 / 기대","depth":3},{"id":"reading-28","label":"금지","depth":3},{"id":"reading-29","label":"과거 예정","depth":3},{"id":"reading-30","label":"연습","depth":2}],"origin":"notion","characters":3482,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-4","topic-4":"reading-5","topic-5":"reading-8","topic-6":"reading-9","topic-7":"reading-10","topic-8":"reading-11","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-16","topic-12":"reading-19"}}]);
